            </div>
            <div>
              <strong>{i18n.t("bench.detail.labels.to")}: </strong>
              <a
                href={`https://github.com/${task()!.task.source.repo}/commit/${task()!.task.source.to}`}
                target="_blank"
                rel="noopener noreferrer"
                style={{ color: "#0066cc" }}
