import type { APIEvent } from "@solidjs/start/server"
import { z } from "zod"
import { Resource } from "@opencode-ai/console-resource"
import { safeEqual } from "@opencode-ai/console-core/util/crypto.js"

const DISCORD_ALERT_ROLE_ID = "1520924666359713863"

const basePayload = z.object({
  name: z.string().optional(),
  status: z.string().optional(),
  isTest: z.boolean().optional(),
  url: z.string(),
})

const groups = z
  .object({
    result: z.union([z.number(), z.string()]).nullish(),
    group: z.object({ key: z.string(), value: z.string() }).array(),
  })
  .array()

const honeycombWebhookPayload = z.discriminatedUnion("type", [
  basePayload.extend({
    type: z.literal("model_http_errors"),
    groups,
  }),
  basePayload.extend({
    type: z.literal("model_low_tps"),
    groups,
  }),
  basePayload.extend({
    type: z.literal("provider_http_errors"),
    groups,
  }),
  basePayload.extend({
    type: z.literal("custom"),
  }),
])

const postDiscordMessage = async (payload: z.infer<typeof honeycombWebhookPayload>) => {
  const names =
    payload.type === "custom"
      ? []
      : payload.groups.flatMap((item) =>
          item.group.map((g) => {
            const result = item.result == null ? undefined : Number(item.result)
            return `- ${g.value}${
              result !== undefined && Number.isFinite(result)
                ? payload.type === "model_low_tps"
                  ? ` (${Math.round(result)} TPS)`
                  : ` (${Math.round(result * 100)}% errors)`
                : ""
            }`
          }),
        )

  const content = [
    `[**${payload.isTest ? "[TEST] " : ""}${payload.name ?? "Honeycomb alert"}**](${payload.url})`,
    ...names,
    "",
    `<@&${DISCORD_ALERT_ROLE_ID}>`,
  ]
    .filter((line) => line !== undefined)
    .join("\n")

  return fetch(Resource.DISCORD_INCIDENT_WEBHOOK_URL.value, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      content,
      allowed_mentions: { roles: [DISCORD_ALERT_ROLE_ID] },
      flags: 4,
    }),
  })
}

export async function POST(input: APIEvent) {
  const token = input.request.headers.get("X-Honeycomb-Webhook-Token")
  if (!safeEqual(token ?? "", Resource.HoneycombWebhookSecret.value)) {
    console.debug("Invalid Honeycomb webhook token")
    return Response.json({ message: "invalid token" }, { status: 401 })
  }

  const body = await input.request.json()
  console.log(body, JSON.stringify(body, null, 2))

  const parsed = honeycombWebhookPayload.safeParse(body)

  if (!parsed.success) {
    console.error(parsed.error)
    return Response.json({ message: "invalid payload" }, { status: 400 })
  }

  if (parsed.data.status !== "TRIGGERED") {
    console.debug("Skipping resolved alert Honeycomb webhook")
    return Response.json({ message: "ignored" }, { status: 200 })
  }

  const response = await postDiscordMessage(parsed.data)
  if (!response.ok) {
    return Response.json({ message: "discord webhook failed" }, { status: 502 })
  }

  return Response.json({ message: "sent" }, { status: 200 })
}

import type { APIEvent } from "@solidjs/start/server"

// OAuth Client ID Metadata Document for the opencode client.
// Spec: https://datatracker.ietf.org/doc/draft-ietf-oauth-client-id-metadata-document/
//
// When an MCP server's authorization server supports this, opencode sends this URL as its OAuth client_id
// instead of registering a new client. The authorization server fetches the document to learn our name and
// allowed redirect URIs. The client_id field must equal the exact URL the document was fetched from, so it is
// built from the request origin and stays valid on dev.opencode.ai as well as production.
//
// redirect_uris have no port because opencode binds an ephemeral port per login. RFC 8252 section 7.3 has
// authorization servers ignore the port when matching loopback redirects for native apps.
const PATH = "/oauth/opencode/client.json"

const cache = "public, max-age=300"

export function GET(event: APIEvent) {
  const origin = new URL(event.request.url).origin
  const document = {
    client_id: origin + PATH,
    client_name: "opencode",
    client_uri: origin,
    logo_uri: origin + "/web-app-manifest-512x512.png",
    application_type: "native",
    redirect_uris: ["http://127.0.0.1/callback", "http://localhost/callback"],
    grant_types: ["authorization_code", "refresh_token"],
    response_types: ["code"],
    token_endpoint_auth_method: "none",
    token_endpoint_auth_methods_supported: ["none"],
  }
  return new Response(JSON.stringify(document, null, 2), {
    headers: {
      "Content-Type": "application/json",
      "Cache-Control": cache,
      "Access-Control-Allow-Origin": "*",
    },
  })
}

