      })()
      const shareUrl = shareId ? `[opencode session](${shareBaseUrl}/s/${shareId})&nbsp;&nbsp;|&nbsp;&nbsp;` : ""
      return `\n\n${image}${shareUrl}[github run](${runUrl})`
    }

