      yield* acp.request<InitializeResponse>("initialize", {
        protocolVersion: 1,
        clientCapabilities: { _meta: { "terminal-auth": true } },
        clientInfo: { name: "opencode-local-acp", version: "0.1.0" },
      }),
    )
  })
}

export function newSession(acp: AcpClient, cwd: string) {
