  const config = testProviderConfig(llmUrl)
  return {
    ...config,
    model: "test/test-model",
    ...(skills ? { skills: { paths: [skills] } } : {}),
    provider: {
      test: {
        ...config.provider.test,
        models: {
          "test-model": {
            ...config.provider.test.models["test-model"],
            variants: {
              low: {},
              high: {},
