    id,
    sessionID: "session-1",
    messageID,
    type: "reasoning",
    text,
    time: { start: 1 },
  }
}

function reasoningUpdated(part: ReasoningPart): SdkEvent {
  return {
    id: `evt-${part.id}-updated`,
    type: "message.part.updated",
    properties: {
      sessionID: part.sessionID,
