              wait += 1
            },
            report: {
              error(_candidate, retry, stage) {
                errors.push([stage, retry])
              },
            },
          }),
        )

        expect(loaded).toEqual([])
        expect(wait).toBe(0)
        expect(errors).toEqual([["install", false]])
      } finally {
        install.mockRestore()
      }
