describe("ProviderTransform.options - google thinkingConfig gating", () => {
  const sessionID = "test-session-123"

  const createGoogleModel = (
    reasoning: boolean,
    npm: "@ai-sdk/google" | "@ai-sdk/google-vertex",
    apiId = "gemini-2.0-flash",
  ) =>
    ({
      id: `${npm === "@ai-sdk/google" ? "google" : "google-vertex"}/${apiId}`,
      providerID: npm === "@ai-sdk/google" ? "google" : "google-vertex",
      api: {
        id: apiId,
        url: npm === "@ai-sdk/google" ? "https://generativelanguage.googleapis.com" : "https://vertexai.googleapis.com",
        npm,
      },
      name: apiId,
      capabilities: {
        temperature: true,
        reasoning,
        attachment: true,
        toolcall: true,
        input: { text: true, audio: false, image: true, video: false, pdf: true },
        output: { text: true, audio: false, image: false, video: false, pdf: false },
        interleaved: false,
      },
      cost: {
        input: 0.001,
        output: 0.002,
        cache: { read: 0.0001, write: 0.0002 },
      },
      limit: {
        context: 1_000_000,
        output: 8192,
      },
      status: "active",
      options: {},
      headers: {},
    }) as any

  test("does not set thinkingConfig for google models without reasoning capability", () => {
    const result = ProviderTransform.options({
      model: createGoogleModel(false, "@ai-sdk/google"),
      sessionID,
      providerOptions: {},
    })
    expect(result.thinkingConfig).toBeUndefined()
  })

  test("sets thinkingConfig for google models with reasoning capability", () => {
    const result = ProviderTransform.options({
      model: createGoogleModel(true, "@ai-sdk/google"),
      sessionID,
      providerOptions: {},
    })
    expect(result.thinkingConfig).toEqual({
      includeThoughts: true,
    })
  })

  test("does not set thinkingConfig for vertex models without reasoning capability", () => {
    const result = ProviderTransform.options({
      model: createGoogleModel(false, "@ai-sdk/google-vertex"),
      sessionID,
      providerOptions: {},
    })
    expect(result.thinkingConfig).toBeUndefined()
  })

  test.each(["gemini-1.5-pro", "gemini-2.0-flash", "gemini-2.5-pro", "gemini-2.5-flash"])(
    "omits default thinkingLevel for legacy model %s",
    (apiId) => {
      for (const npm of ["@ai-sdk/google", "@ai-sdk/google-vertex"] as const) {
        const result = ProviderTransform.options({
          model: createGoogleModel(true, npm, apiId),
          sessionID,
          providerOptions: {},
        })
        expect(result.thinkingConfig).toEqual({
          includeThoughts: true,
        })
      }

      const openrouterResult = ProviderTransform.options({
        model: {
          ...createGoogleModel(true, "@ai-sdk/google", `google/${apiId}`),
          providerID: "openrouter",
          api: {
            id: `google/${apiId}`,
            url: "https://openrouter.ai/api/v1",
            npm: "@openrouter/ai-sdk-provider",
          },
        },
        sessionID,
        providerOptions: {},
      })
      expect(openrouterResult.reasoning).toBeUndefined()
    },
  )

  test.each([
    "gemini-3-pro-preview",
    "gemini-3-flash-preview",
    "gemini-9-pro",
    "gemini-9-flash",
    "gemini-pro-latest",
    "gemini-flash-latest",
  ])("sets default thinkingLevel=high and OpenRouter reasoning effort=high for %s", (apiId) => {
    for (const npm of ["@ai-sdk/google", "@ai-sdk/google-vertex"] as const) {
      const result = ProviderTransform.options({
        model: createGoogleModel(true, npm, apiId),
        sessionID,
        providerOptions: {},
      })
      expect(result.thinkingConfig).toEqual({
        includeThoughts: true,
        thinkingLevel: "high",
      })
    }

    const openrouterResult = ProviderTransform.options({
      model: {
        ...createGoogleModel(true, "@ai-sdk/google", `google/${apiId}`),
        providerID: "openrouter",
        api: {
          id: `google/${apiId}`,
          url: "https://openrouter.ai/api/v1",
          npm: "@openrouter/ai-sdk-provider",
        },
      },
      sessionID,
      providerOptions: {},
    })
    expect(openrouterResult.reasoning).toEqual({ effort: "high" })
  })
})

