import { Resource } from "sst/resource"

const listId = "8b9bb82c-9d5f-11f0-975f-0df6fd1e4945"

export async function POST(event: { request: Request }) {
  const contentType = event.request.headers.get("content-type") ?? ""
  if (!contentType.includes("multipart/form-data") && !contentType.includes("application/x-www-form-urlencoded")) {
    return Response.json({ error: "Email address is required" }, { status: 400 })
  }

  const form = await event.request.formData()
  const emailAddress = form.get("email")
  if (typeof emailAddress !== "string" || emailAddress.trim().length === 0) {
    return Response.json({ error: "Email address is required" }, { status: 400 })
  }

  const response = await fetch(`https://api.emailoctopus.com/lists/${listId}/contacts`, {
    method: "PUT",
    headers: {
      Authorization: `Bearer ${Resource.EMAILOCTOPUS_API_KEY.value}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({
      email_address: emailAddress.trim(),
    }),
  })
  if (!response.ok) return Response.json({ error: "Failed to subscribe" }, { status: 502 })
  return Response.json({ success: true })
}

import { Select } from "@kobalte/core/select"
import { createMemo } from "solid-js"

export type BreadcrumbSelectOption = {
  href: string
  label: string
  value: string
}

export function BreadcrumbSelect(props: {
  ariaLabel: string
  current?: boolean
  label: string
  options: BreadcrumbSelectOption[]
  value: string
  variant: "lab" | "model"
}) {
  const selected = createMemo(() => props.options.find((option) => option.value === props.value) ?? null)

  return (
    <Select<BreadcrumbSelectOption>
      data-component="stats-breadcrumb-select"
      data-variant={props.variant}
      options={props.options}
      optionValue="value"
      optionTextValue="label"
      value={selected()}
      placeholder={props.label}
      disallowEmptySelection
      closeOnSelection
      shouldFocusWrap
      placement="bottom"
      gutter={8}
      sameWidth={false}
      itemComponent={(itemProps) => (
        <Select.Item
          item={itemProps.item}
          data-slot="stats-breadcrumb-select-option"
          data-current={itemProps.item.rawValue.value === props.value ? "true" : undefined}
        >
          <Select.ItemLabel>{itemProps.item.rawValue.label}</Select.ItemLabel>
        </Select.Item>
      )}
      onChange={(option) => {
        if (!option || option.value === props.value) return
        window.location.assign(option.href)
      }}
    >
      <Select.Trigger
        data-slot="stats-breadcrumb-select-trigger"
        data-current={props.current ? "true" : undefined}
        data-variant={props.variant}
        aria-label={props.ariaLabel}
        aria-current={props.current ? "page" : undefined}
      >
        <Select.Value<BreadcrumbSelectOption> data-slot="stats-breadcrumb-select-value">
          {(state) => <span>{state.selectedOption()?.label ?? props.label}</span>}
        </Select.Value>
        <Select.Icon data-slot="stats-breadcrumb-select-icon">
          <svg width="16" height="16" viewBox="0 0 16 16" aria-hidden="true">
            <path d="M5 6.5L8 9.5L11 6.5" fill="none" stroke="currentColor" />
          </svg>
        </Select.Icon>
      </Select.Trigger>
      <Select.HiddenSelect />
      <Select.Content data-component="stats-breadcrumb-select-content" data-variant={props.variant}>
        <Select.Listbox data-slot="stats-breadcrumb-select-listbox" />
      </Select.Content>
    </Select>
  )
}

import { ProviderIcon } from "@opencode-ai/ui/provider-icon"
import { For, Show } from "solid-js"
import { catalogSlug, formatCatalogLabName, type ModelCatalogEntry } from "./model-catalog"

export type ComparisonModelRef = {
  name: string
  lab: string
  slug: string
  labName?: string
  metric?: string
}

export type ComparisonPair = {
  first: ComparisonModelRef
  second: ComparisonModelRef
  detail: string
  description?: string
}

export function modelRefFromCatalog(entry: Pick<ModelCatalogEntry, "name" | "lab" | "slug">): ComparisonModelRef {
  return {
    name: entry.name,
    lab: entry.lab,
    slug: entry.slug,
    labName: formatCatalogLabName(entry.lab),
  }
}

export function comparisonHref(first: ComparisonModelRef, second: ComparisonModelRef) {
  return `${import.meta.env.BASE_URL}compare/${catalogSlug(first.lab)}/${catalogSlug(first.slug)}/${catalogSlug(
    second.lab,
  )}/${catalogSlug(second.slug)}`
}

export function canonicalComparisonHref(first: ComparisonModelRef, second: ComparisonModelRef) {
  const models = [first, second].toSorted((a, b) => modelKey(a).localeCompare(modelKey(b)))
  return comparisonHref(models[0], models[1])
}

export function uniqueComparisonPairs(pairs: ComparisonPair[]) {
  return pairs.reduce<{ keys: Set<string>; pairs: ComparisonPair[] }>(
    (result, pair) => {
      const key = [modelKey(pair.first), modelKey(pair.second)].toSorted().join("|")
      if (result.keys.has(key) || modelKey(pair.first) === modelKey(pair.second)) return result
      result.keys.add(key)
      result.pairs.push(pair)
      return result
    },
    { keys: new Set(), pairs: [] },
  ).pairs
}

export function ComparisonCardsSection(props: {
  pairs: ComparisonPair[]
  title?: string
  description?: string
  compact?: boolean
  variant?: "panel" | "featured"
}) {
  const featured = () => props.variant === "featured"
  const pairs = () => (featured() ? props.pairs.slice(0, 4) : props.pairs)

  return (
    <Show when={props.pairs.length > 0}>
      <section
        id="model-comparison"
        data-section={featured() ? "compare-home-related" : "model-panel"}
        data-variant={!featured() && props.compact ? "compact" : undefined}
      >
        <p data-slot="section-title">
          <strong>{props.title ?? "Model Comparisons"}.</strong>{" "}
          <span>{props.description ?? "Compare usage, cost, limits, and features."}</span>
        </p>
        <div data-component={featured() ? "compare-home-card-grid" : "comparison-card-grid"}>
          <For each={pairs()}>
            {(pair) => (featured() ? <FeaturedComparisonCard pair={pair} /> : <ComparisonPanelCard pair={pair} />)}
          </For>
        </div>
      </section>
    </Show>
  )
}

function FeaturedComparisonCard(props: { pair: ComparisonPair }) {
  return (
    <a data-component="compare-home-card" href={canonicalComparisonHref(props.pair.first, props.pair.second)}>
      <span data-slot="compare-home-card-head">
        <span>
          <strong>{props.pair.detail}</strong>
          <em>{props.pair.description ?? `${props.pair.first.name} vs ${props.pair.second.name}`}</em>
        </span>
        <ComparisonCardIcon />
      </span>
      <span data-slot="compare-home-card-divider" aria-hidden="true" />
      <span data-slot="compare-home-card-models">
        <span>{props.pair.first.name}</span>
        <i aria-hidden="true">·</i>
        <span>{props.pair.second.name}</span>
      </span>
      <span data-slot="compare-home-card-avatars" aria-hidden="true">
        <ComparisonLabLogo model={props.pair.first} />
        <ComparisonLabLogo model={props.pair.second} />
      </span>
    </a>
  )
}

function ComparisonCardIcon() {
  return (
    <b aria-hidden="true">
      <svg width="16" height="16" viewBox="0 0 16 16" fill="none" xmlns="http://www.w3.org/2000/svg">
        <path
          d="M12.9509 12.9884L14.4069 14.4444M2.44431 2.44434H6.44431V6.44434H2.44431V2.44434ZM2.44431 9.55542H6.44431V13.5554H2.44431V9.55542ZM9.55539 2.44434H13.5554V6.44434H9.55539V2.44434ZM13.5554 11.5554C13.5554 12.66 12.66 13.5554 11.5554 13.5554C10.4508 13.5554 9.55539 12.66 9.55539 11.5554C9.55539 10.4509 10.4508 9.55542 11.5554 9.55542C12.66 9.55542 13.5554 10.4509 13.5554 11.5554Z"
          stroke="#808080"
        />
      </svg>
    </b>
  )
}

function ComparisonPanelCard(props: { pair: ComparisonPair }) {
  const firstLabName = () => props.pair.first.labName
  const secondLabName = () => props.pair.second.labName

  return (
    <a data-component="comparison-card" href={canonicalComparisonHref(props.pair.first, props.pair.second)}>
      <span>{props.pair.detail}</span>
      <strong>
        {props.pair.first.name} <em>vs</em> {props.pair.second.name}
      </strong>
      <Show when={firstLabName() || secondLabName()}>
        <p>
          <Show when={firstLabName()}>{(name) => <b>{name()}</b>}</Show>
          <Show when={firstLabName() && secondLabName()}>
            <i />
          </Show>
          <Show when={secondLabName()}>{(name) => <b>{name()}</b>}</Show>
        </p>
      </Show>
      <Show when={props.pair.first.metric || props.pair.second.metric}>
        <small>
          {props.pair.first.metric ?? "Listed"} / {props.pair.second.metric ?? "Listed"}
        </small>
      </Show>
    </a>
  )
}

function ComparisonLabLogo(props: { model: ComparisonModelRef }) {
  const iconId = () => providerIconId(props.model.lab)

  return (
    <Show when={props.model.labName}>
      <span data-slot="compare-home-avatar" data-lab={iconId()} data-size="small" aria-label={props.model.labName}>
        <ProviderIcon aria-hidden="true" id={iconId()} />
      </span>
    </Show>
  )
}

function modelKey(model: ComparisonModelRef) {
  return `${catalogSlug(model.lab)}/${catalogSlug(model.slug)}`
}

function providerIconId(provider: string) {
  const id = provider.toLowerCase().replace(/[^a-z0-9]+/g, "")
  if (id === "moonshot") return "moonshotai"
  if (id === "zhipu") return "zhipuai"
  return id
}

import { createMemo, createSignal, For, Show, type JSX } from "solid-js"
import type { ModelCatalogBenchmark, ModelCatalogEntry } from "./model-catalog"

const radarRingCount = 5
const radarColors = ["#294bdb", "#159447", "#d24a3b", "#8a4fd2", "#b47400", "#008c95"] as const
const codingBenchmarkPattern = /(swe|aider|code|coding|nl2repo)/
const reasoningBenchmarkPattern = /(gpqa|humanity|last exam|reasoning|aime|hmmt|math|mmlu|mrcr|charxiv|cti realm)/
const toolUseBenchmarkPattern = /(terminal bench|claw eval|tau ?(?:bench|2|3))/

export type ComparisonRadarModel = {
  name: string
  labName?: string
  catalog: ModelCatalogEntry | null
}

type ComparisonRadarProps = {
  models: readonly ComparisonRadarModel[]
  catalogModels: readonly ModelCatalogEntry[]
}

type RadarAxis = {
  label: string
  description: string
  score: (model: ModelCatalogEntry) => number | undefined
  capability?: "reasoning" | "toolCall"
}

type RadarScore = {
  value: number
  fallback?: string
}

type RadarPoint = {
  x: number
  y: number
}

export function ComparisonRadar(props: ComparisonRadarProps) {
  const [activeAxis, setActiveAxis] = createSignal<number>()
  const axes = createMemo(() => buildRadarAxes(props.catalogModels))
  const series = createMemo(() =>
    props.models.map((model, index) => ({
      name: model.name,
      labName: model.labName,
      color: radarColors[index % radarColors.length],
      scores: axes().map((axis) => resolveRadarScore(axis, model.catalog)),
    })),
  )
  const accessibleDescription = createMemo(() =>
    series()
      .map(
        (model) =>
          `${model.name}: ${axes()
            .map((axis, index) => `${axis.label} ${formatRadarScore(model.scores[index])}`)
            .join(", ")}`,
      )
      .join(". "),
  )
  const clearActiveAxis = (index: number) => setActiveAxis((active) => (active === index ? undefined : active))

  return (
    <section data-section="compare-radar" aria-label="Model capabilities">
      <ol data-slot="compare-radar-legend">
        <For each={series()}>
          {(model) => (
            <li>
              <i style={{ background: model.color }} aria-hidden="true" />
              <span>
                <strong>{model.name}</strong>
                <Show when={model.labName}>{(name) => <small>{name()}</small>}</Show>
                <Show when={model.scores.some((score) => score.fallback)}>
                  <small data-slot="compare-radar-coverage">Hollow points use fallbacks · hover for details</small>
                </Show>
              </span>
            </li>
          )}
        </For>
      </ol>
      <div data-slot="compare-radar-chart" role="img" aria-label={accessibleDescription()}>
        <div data-slot="compare-radar-plot" aria-hidden="true">
          <svg viewBox="0 0 100 100" preserveAspectRatio="xMidYMid meet">
            <g data-slot="compare-radar-grid">
              <For each={Array.from({ length: radarRingCount })}>
                {(_, index) => (
                  <polygon points={radarPolygonPoints(axes().length, ((index() + 1) / radarRingCount) * 100)} />
                )}
              </For>
              <For each={axes()}>
                {(_, index) => {
                  const point = () => radarPoint(index(), axes().length, 100)
                  return <line x1="50" y1="50" x2={point().x} y2={point().y} />
                }}
              </For>
            </g>
            <For each={series()}>
              {(model) => (
                <g data-slot="compare-radar-series" style={{ color: model.color }}>
                  <polygon data-slot="compare-radar-area" points={radarSeriesPolygon(model.scores)} />
                  <For each={model.scores}>
                    {(score, index) => {
                      const point = () => radarPoint(index(), axes().length, score.value)
                      return (
                        <>
                          <circle
                            data-slot="compare-radar-point"
                            data-fallback={score.fallback ? "true" : undefined}
                            cx={point().x}
                            cy={point().y}
                            r="0.95"
                          />
                          <circle
                            data-slot="compare-radar-point-hit"
                            cx={point().x}
                            cy={point().y}
                            r="3"
                            onMouseEnter={() => setActiveAxis(index())}
                            onMouseLeave={() => clearActiveAxis(index())}
                          />
                        </>
                      )
                    }}
                  </For>
                </g>
              )}
            </For>
          </svg>
        </div>
        <For each={axes()}>
          {(axis, index) => (
            <span
              data-slot="compare-radar-axis"
              data-active={activeAxis() === index() ? "true" : undefined}
              style={radarAxisStyle(index(), axes().length)}
              tabIndex="0"
              aria-label={`${axis.label}. ${axis.description}`}
              onMouseEnter={() => setActiveAxis(index())}
              onMouseLeave={() => clearActiveAxis(index())}
              onFocus={() => setActiveAxis(index())}
              onBlur={() => clearActiveAxis(index())}
              onKeyDown={(event) => {
                if (event.key === "Escape") event.currentTarget.blur()
              }}
            >
              <span data-slot="compare-radar-axis-label">{axis.label}</span>
            </span>
          )}
        </For>
        <Show when={activeAxis() !== undefined}>
          <div
            data-slot="compare-radar-tooltip"
            role="tooltip"
            style={radarTooltipStyle(activeAxis() ?? 0, axes().length)}
          >
            <strong>{axes()[activeAxis() ?? 0]?.label}</strong>
            <p>{axes()[activeAxis() ?? 0]?.description}</p>
            <For each={series()}>
              {(model) => (
                <p>
                  {model.name}: {formatRadarScore(model.scores[activeAxis() ?? 0])}
                </p>
              )}
            </For>
          </div>
        </Show>
      </div>
      <div data-slot="compare-radar-data">
        <table>
          <caption>Normalized model capability scores</caption>
          <thead>
            <tr>
              <th>Model</th>
              <For each={axes()}>{(axis) => <th>{axis.label}</th>}</For>
            </tr>
          </thead>
          <tbody>
            <For each={series()}>
              {(model) => (
                <tr>
                  <th>{model.name}</th>
                  <For each={model.scores}>{(score) => <td>{formatRadarScore(score)}</td>}</For>
                </tr>
              )}
            </For>
          </tbody>
        </table>
      </div>
    </section>
  )
}

export function buildRadarAxes(catalogModels: readonly ModelCatalogEntry[]): RadarAxis[] {
  const benchmarks = benchmarkScoreGroups(catalogModels)
  const toolUseBenchmarks = benchmarkScoreGroups(catalogModels, true)
  const costs = catalogModels.flatMap((model) => {
    const cost = modelCost(model)
    return cost === undefined ? [] : [cost]
  })
  const contexts = catalogModels.flatMap((model) => (model.limit?.context === undefined ? [] : [model.limit.context]))
  const multimodalMaximum = Math.max(...catalogModels.map(multimodalFeatureCount), 0)

  // Speed and safety stay out until the catalog exposes comparable values for them.
  return [
    {
      label: "Reasoning",
      capability: "reasoning",
      description:
        "Ability to solve complex, multi-step problems. Benchmarks take priority; reasoning support defaults to 50/100.",
      score: (model) => benchmarkPercentile(model, benchmarks, reasoningBenchmarkPattern),
    },
    {
      label: "Coding",
      description: "Performance on software engineering and coding benchmarks.",
      score: (model) => benchmarkPercentile(model, benchmarks, codingBenchmarkPattern),
    },
    {
      label: "Cost efficiency",
      description: "Relative input and output pricing. Lower-cost models score higher.",
      score: (model) => {
        const cost = modelCost(model)
        if (cost === undefined) return
        if (cost === 0) return 100
        return percentileScore(cost, costs, "lower")
      },
    },
    {
      label: "Context window",
      description: "How much input the model can process at once. Larger context windows score higher.",
      score: (model) => {
        const context = model.limit?.context
        if (context === undefined) return
        return percentileScore(context, contexts, "higher")
      },
    },
    {
      label: "Multimodal",
      description: "Support for non-text input and output, including images, audio, and video.",
      score: (model) => {
        if (multimodalMaximum === 0) return
        return (multimodalFeatureCount(model) / multimodalMaximum) * 100
      },
    },
    {
      label: "Tool use",
      capability: "toolCall",
      description: "Agent benchmark performance. Benchmarks take priority; tool calling support defaults to 50/100.",
      score: (model) =>
        benchmarkPercentile(model, toolUseBenchmarks, toolUseBenchmarkPattern, {
          aggregate: "average",
          includeHarness: true,
        }),
    },
  ]
}

function benchmarkScoreGroups(catalogModels: readonly ModelCatalogEntry[], includeHarness = false) {
  return catalogModels.reduce<Map<string, number[]>>((groups, model) => {
    model.benchmarks
      .reduce<Map<string, number>>((scores, benchmark) => {
        const key = benchmarkKey(benchmark, includeHarness)
        scores.set(key, Math.max(scores.get(key) ?? -Infinity, benchmark.score))
        return scores
      }, new Map())
      .forEach((score, key) => {
        groups.set(key, [...(groups.get(key) ?? []), score])
      })
    return groups
  }, new Map())
}

function benchmarkKey(benchmark: ModelCatalogBenchmark, includeHarness: boolean) {
  const name = normalizeBenchmarkName(benchmark.name)
  const version = normalizeBenchmarkName(benchmark.version ?? "")
  const versioned = version && !name.endsWith(version) ? `${name} ${version}` : name
  if (!includeHarness) return versioned
  const harness = normalizeBenchmarkName(benchmark.harness ?? benchmark.variant ?? "")
  return harness ? `${versioned} | ${harness}` : versioned
}

function benchmarkPercentile(
  model: ModelCatalogEntry,
  benchmarks: Map<string, number[]>,
  pattern: RegExp,
  options?: { aggregate?: "average" | "best"; includeHarness?: boolean },
) {
  const scores = Object.entries(
    model.benchmarks.reduce<Record<string, number>>((result, benchmark) => {
      const key = benchmarkKey(benchmark, options?.includeHarness ?? false)
      if (!pattern.test(key)) return result
      result[key] = Math.max(result[key] ?? -Infinity, benchmark.score)
      return result
    }, {}),
  ).flatMap(([key, score]) => {
    const values = benchmarks.get(key)
    const percentile = values ? percentileScore(score, values, "higher") : undefined
    return percentile === undefined ? [] : [percentile]
  })
  if (scores.length === 0) return
  if (options?.aggregate === "average") return scores.reduce((sum, score) => sum + score, 0) / scores.length
  // Benchmark coverage varies by model, so additional published results should not lower a model's score.
  return Math.max(...scores)
}

function normalizeBenchmarkName(value: string) {
  return value
    .toLowerCase()
    .replace(/\u03c4/g, "tau")
    .replace(/\u00b2/g, "2")
    .replace(/\u00b3/g, "3")
    .replace(/[^a-z0-9]+/g, " ")
    .trim()
}

function modelCost(model: ModelCatalogEntry) {
  if (!model.cost) return
  return model.cost.input + model.cost.output
}

function multimodalFeatureCount(model: ModelCatalogEntry) {
  return new Set([
    ...model.modalities.input.filter((modality) => modality !== "text").map((modality) => `input:${modality}`),
    ...model.modalities.output.filter((modality) => modality !== "text").map((modality) => `output:${modality}`),
    ...(model.attachment ? ["attachment"] : []),
  ]).size
}

function percentileScore(value: number, values: number[], direction: "higher" | "lower") {
  const finite = values.filter(Number.isFinite)
  if (!Number.isFinite(value) || finite.length < 2) return
  const below = finite.filter((candidate) => candidate < value).length
  const equal = finite.filter((candidate) => candidate === value).length
  const percentile = ((below + (equal - 1) / 2) / (finite.length - 1)) * 100
  return direction === "higher" ? percentile : 100 - percentile
}

function radarPoint(index: number, count: number, score: number): RadarPoint {
  const angle = -Math.PI / 2 + (index * Math.PI * 2) / count
  const radius = Math.max(0, Math.min(100, score)) / 2
  return {
    x: roundRadarCoordinate(50 + Math.cos(angle) * radius),
    y: roundRadarCoordinate(50 + Math.sin(angle) * radius),
  }
}

function radarPolygonPoints(count: number, score: number) {
  return Array.from({ length: count })
    .map((_, index) => radarPoint(index, count, score))
    .map((point) => `${point.x},${point.y}`)
    .join(" ")
}

function radarSeriesPolygon(scores: RadarScore[]) {
  return scores
    .map((score, index) => radarPoint(index, scores.length, score.value))
    .map((point) => `${point.x},${point.y}`)
    .join(" ")
}

function radarAxisStyle(index: number, count: number) {
  const angle = -Math.PI / 2 + (index * Math.PI * 2) / count
  const horizontal = Math.cos(angle)
  return {
    "--compare-radar-axis-x": `${roundRadarCoordinate(50 + horizontal * 42)}%`,
    "--compare-radar-axis-mobile-x": `${roundRadarCoordinate(50 + horizontal * 36)}%`,
    "--compare-radar-axis-y": `${roundRadarCoordinate(50 + Math.sin(angle) * 42)}%`,
    "--compare-radar-axis-translate-x": horizontal > 0.25 ? "0%" : horizontal < -0.25 ? "-100%" : "-50%",
  } as JSX.CSSProperties
}

function radarTooltipStyle(index: number, count: number) {
  const angle = -Math.PI / 2 + (index * Math.PI * 2) / count
  return {
    "--compare-radar-tooltip-x": `${roundRadarCoordinate(50 + Math.cos(angle) * 42)}%`,
    "--compare-radar-tooltip-y": `${roundRadarCoordinate(50 + Math.sin(angle) * 42)}%`,
    "--compare-radar-tooltip-translate-y": Math.sin(angle) < -0.9 ? "20px" : "calc(-100% - 12px)",
  } as JSX.CSSProperties
}

function roundRadarCoordinate(value: number) {
  return Math.round(value * 1000) / 1000
}

function formatRadarScore(score: RadarScore) {
  return `${Math.round(score.value)}/100${score.fallback ? ` — ${score.fallback}` : ""}`
}

export function resolveRadarScore(axis: RadarAxis, model: ModelCatalogEntry | null): RadarScore {
  const score = model ? axis.score(model) : undefined
  if (score !== undefined) return { value: score }
  const supported = axis.capability ? model?.[axis.capability] : undefined
  if (supported === undefined) return { value: 50, fallback: "No data; neutral placeholder" }
  const capability = axis.capability === "toolCall" ? "Tool calling" : "Reasoning"
  return supported
    ? { value: 50, fallback: `${capability} supported; no comparable benchmark` }
    : { value: 0, fallback: `${capability} not supported` }
}

import { createEffect, createMemo, createSignal, For } from "solid-js"
import { comparisonHref, modelRefFromCatalog } from "./compare-cards"
import type { ModelCatalogEntry } from "./model-catalog"

export function ComparisonSelector(props: {
  models: ModelCatalogEntry[]
  firstId?: string
  secondId?: string
  label?: string
}) {
  const [firstId, setFirstId] = createSignal(props.firstId ?? props.models[0]?.id ?? "")
  const [secondId, setSecondId] = createSignal(differentModelId(props.models, firstId(), props.secondId))
  const modelById = createMemo(() => new Map(props.models.map((model) => [model.id, model])))
  const href = createMemo(() => {
    const first = modelById().get(firstId())
    const second = modelById().get(secondId())
    if (!first || !second || first.id === second.id) return undefined
    return comparisonHref(modelRefFromCatalog(first), modelRefFromCatalog(second))
  })

  createEffect(() => {
    if (firstId() && modelById().has(firstId())) return
    const next = props.firstId && modelById().has(props.firstId) ? props.firstId : props.models[0]?.id
    if (next) setFirstId(next)
  })

  createEffect(() => {
    if (secondId() && secondId() !== firstId() && modelById().has(secondId())) return
    setSecondId(differentModelId(props.models, firstId(), props.secondId))
  })

  return (
    <form
      data-component="comparison-selector"
      aria-label={props.label ?? "Model comparison selector"}
      onSubmit={(event) => {
        event.preventDefault()
        const url = href()
        if (!url || typeof window === "undefined") return
        window.location.href = url
      }}
    >
      <label>
        <span>First model</span>
        <select value={firstId()} onInput={(event) => setFirstId(event.currentTarget.value)} required>
          <option value="" disabled>
            Select model
          </option>
          <For each={props.models}>
            {(model) => (
              <option value={model.id}>
                {model.name} ({model.lab})
              </option>
            )}
          </For>
        </select>
      </label>
      <label>
        <span>Second model</span>
        <select value={secondId()} onInput={(event) => setSecondId(event.currentTarget.value)} required>
          <option value="" disabled>
            Select model
          </option>
          <For each={props.models}>
            {(model) => (
              <option value={model.id} disabled={model.id === firstId()}>
                {model.name} ({model.lab})
              </option>
            )}
          </For>
        </select>
      </label>
      <button type="submit" disabled={!href()}>
        Compare models
      </button>
    </form>
  )
}

function differentModelId(models: ModelCatalogEntry[], firstId: string, preferredId: string | undefined) {
  if (preferredId && preferredId !== firstId && models.some((model) => model.id === preferredId)) return preferredId
  return models.find((model) => model.id !== firstId)?.id ?? ""
}

import { Meta, Title } from "@solidjs/meta"
import { createAsync, useParams } from "@solidjs/router"
import { createMemo, Show } from "solid-js"
import ModelCompareDetailPage from "../../../component/model-compare-detail"
import { resolveComparisonFamily } from "../../../lib/comparison-pages"
import { getModelCatalog } from "../../model-catalog"

export default function ModelCompareFamily() {
  const params = useParams()
  const catalog = createAsync(() => getModelCatalog())
  const comparison = createMemo(() => {
    const source = catalog()
    if (!source) return undefined
    const first = resolveComparisonFamily(source, params.firstFamily ?? "")
    const second = resolveComparisonFamily(source, params.secondFamily ?? "")
    if (!first || !second || first.slug === second.slug) return null
    return { first, second }
  })

  return (
    <Show
      when={comparison()}
      fallback={
        <Show when={comparison() === null}>
          <Title>Model comparison not found</Title>
          <Meta name="robots" content="noindex,follow" />
          <main data-page="stats">
            <div data-component="empty-state">
              <strong>Comparison not found</strong>
              <p>Choose two model families to compare.</p>
              <a href={`${import.meta.env.BASE_URL}compare`}>Compare models</a>
            </div>
          </main>
        </Show>
      }
    >
      {(resolved) => (
        <ModelCompareDetailPage
          first={{ lab: resolved().first.model.lab, slug: resolved().first.model.slug }}
          second={{ lab: resolved().second.model.lab, slug: resolved().second.model.slug }}
          family={resolved()}
          catalog={catalog()}
        />
      )}
    </Show>
  )
}

import { Meta, Title } from "@solidjs/meta"
import { ProviderIcon } from "@opencode-ai/ui/provider-icon"
import { createAsync } from "@solidjs/router"
import { createEffect, createMemo, createSignal, For, onMount, Show } from "solid-js"
import { getRequestEvent } from "solid-js/web"
import { LocaleLinks } from "../../component/locale-links"
import { useI18n } from "../../context/i18n"
import { useLanguage } from "../../context/language"
import { localizedUrl } from "../../lib/language"
import {
  ComparisonCardsSection,
  comparisonHref,
  modelRefFromCatalog,
  type ComparisonModelRef,
  type ComparisonPair,
} from "../compare-cards"
import { formatCatalogLabName, getModelCatalog, type ModelCatalogEntry } from "../model-catalog"
import { setStatsPageCacheHeaders } from "../stats-cache"
import {
  applyThemePreference,
  Footer,
  getGitHubStars,
  githubLink,
  Header,
  isThemePreference,
  themeStorageKey,
  type HeaderLink,
  type ThemePreference,
} from "../stats-shell"

const comparePath = "/data/compare"
const compareTitle = "AI Model Comparison"
const compareDescription =
  "Compare AI models on key metrics including benchmarks, price, context length, and other model features."
const statsUnfurlPath = "banner.png"
const uptimeBars = Array.from({ length: 10 }, (_, index) => index)
const heroLabs = [
  { lab: "deepseek", label: "DeepSeek" },
  { lab: "openai", label: "OpenAI" },
  { lab: "anthropic", label: "Anthropic" },
] as const
const categoryTemplates = [
  {
    title: "Flagship models",
    description: "The latest top-tier model from major labs.",
    kind: "flagship",
  },
  {
    title: "Most affordable",
    description: "Compact, lower-cost picks for high-throughput use.",
    kind: "affordable",
  },
  {
    title: "Best for code",
    description: "Frequently chosen for programming tasks.",
    kind: "code",
  },
  {
    title: "Image generation",
    description: "Compare top image models on cost and quality.",
    kind: "image",
  },
] as const

type CompareSlot = "first" | "second"

export default function ModelCompareIndex() {
  const i18n = useI18n()
  const language = useLanguage()
  const event = getRequestEvent()
  setStatsPageCacheHeaders(event?.response.headers)
  const catalog = createAsync(() => getModelCatalog())
  const githubStars = createAsync(() => getGitHubStars())
  const [themePreference, setThemePreference] = createSignal<ThemePreference>("system")
  const compareUrl = createMemo(() => localizedUrl(language.locale(), comparePath))
  const statsUnfurlUrl = new URL(statsUnfurlPath, localizedUrl("en", "/data/")).toString()
  const models = createMemo(() => catalog()?.models ?? [])
  const featuredModels = createMemo(() => models().slice(0, 120))
  const categories = createMemo(() => buildComparisonCategories(featuredModels()))
  const compareHeaderLinks = createMemo<readonly HeaderLink[]>(() => [
    { href: `${import.meta.env.BASE_URL}#top-models`, label: i18n.t("nav.topModels") },
    { href: `${import.meta.env.BASE_URL}#leaderboard`, label: i18n.t("nav.leaderboard") },
    { href: `${import.meta.env.BASE_URL}#market-share`, label: i18n.t("nav.marketShare") },
    { href: `${import.meta.env.BASE_URL}#token-cost`, label: i18n.t("nav.tokenCost") },
    { href: `${import.meta.env.BASE_URL}#session-cost`, label: i18n.t("nav.sessionCost") },
  ])
  const compareFooterLinks = createMemo<readonly HeaderLink[]>(() => [
    { href: `${import.meta.env.BASE_URL}#top-models`, label: i18n.t("nav.topModels") },
    { href: `${import.meta.env.BASE_URL}#leaderboard`, label: i18n.t("nav.leaderboard") },
    { href: `${import.meta.env.BASE_URL}#market-share`, label: i18n.t("nav.marketShare") },
    { href: `${import.meta.env.BASE_URL}#token-cost`, label: i18n.t("nav.tokenCost") },
    { href: `${import.meta.env.BASE_URL}#session-cost`, label: i18n.t("nav.sessionCost") },
  ])
  const updateThemePreference = (preference: ThemePreference) => {
    applyThemePreference(preference)
    setThemePreference(preference)
    if (typeof window === "undefined") return
    window.localStorage.setItem(themeStorageKey, preference)
  }

  onMount(() => {
    if (typeof window === "undefined") return
    const preference = window.localStorage.getItem(themeStorageKey)
    const nextPreference = isThemePreference(preference) ? preference : "system"
    applyThemePreference(nextPreference)
    setThemePreference(nextPreference)
  })

  return (
    <main data-page="stats" data-theme={themePreference()}>
      <Title>{compareTitle}</Title>
      <Meta name="description" content={compareDescription} />
      <LocaleLinks path={comparePath} />
      <Meta property="og:type" content="website" />
      <Meta property="og:site_name" content="OpenCode" />
      <Meta property="og:title" content={compareTitle} />
      <Meta property="og:description" content={compareDescription} />
      <Meta property="og:url" content={compareUrl()} />
      <Meta property="og:image" content={statsUnfurlUrl} />
      <Meta property="og:image:type" content="image/png" />
      <Meta property="og:image:width" content="1200" />
      <Meta property="og:image:height" content="630" />
      <Meta property="og:image:alt" content={i18n.t("app.unfurlAlt")} />
      <Meta name="twitter:card" content="summary_large_image" />
      <Meta name="twitter:title" content={compareTitle} />
      <Meta name="twitter:description" content={compareDescription} />
      <Meta name="twitter:image" content={statsUnfurlUrl} />
      <Meta name="twitter:image:alt" content={i18n.t("app.unfurlAlt")} />
      <Header
        githubStars={githubStars() ?? githubLink.fallbackStars}
        links={compareHeaderLinks()}
        brandHref={import.meta.env.BASE_URL}
      />
      <div data-component="container">
        <div data-component="content">
          <section id="compare-tool" data-section="compare-home-hero">
            <nav data-component="compare-home-breadcrumb" aria-label="Breadcrumb">
              <a data-slot="compare-home-crumb" href={language.route(import.meta.env.BASE_URL)}>
                Data
              </a>
              <span data-slot="compare-home-separator">/</span>
              <span data-slot="compare-home-crumb" data-current="true" aria-current="page">
                Compare
              </span>
            </nav>
            <div data-slot="compare-home-hero-grid">
              <h1 aria-label="Compare AI models">
                <span>Compare</span>
                <HeroModelStack />
                <span>AI models</span>
              </h1>
              <p>{compareDescription}</p>
            </div>
            <div data-slot="compare-home-pattern" aria-hidden="true" />
          </section>
          <section data-section="compare-home-selector" aria-label="Choose models to compare">
            <Show
              when={models().length > 1}
              fallback={
                <div data-component="empty-state" data-compact="true">
                  <strong>No models found</strong>
                  <p>The model list could not be loaded.</p>
                </div>
              }
            >
              <CompareHomeSelector models={models()} />
            </Show>
          </section>
          <ComparisonCardsSection
            pairs={categories()}
            title="Related comparisons"
            description="Other model pairs to check."
            variant="featured"
          />
        </div>
        <Footer
          themePreference={themePreference()}
          onThemePreferenceChange={updateThemePreference}
          links={compareFooterLinks()}
          bridge={null}
        />
      </div>
    </main>
  )
}

function CompareHomeSelector(props: { models: ModelCatalogEntry[] }) {
  const [firstId, setFirstId] = createSignal("")
  const [secondId, setSecondId] = createSignal("")
  const [activeSlot, setActiveSlot] = createSignal<CompareSlot>()
  const modelById = createMemo(() => new Map(props.models.map((model) => [model.id, model])))
  const first = createMemo(() => modelById().get(firstId()))
  const second = createMemo(() => modelById().get(secondId()))
  const activeSelected = createMemo(() => (activeSlot() === "first" ? first() : second()))
  const activeBlockedId = createMemo(() => (activeSlot() === "first" ? secondId() : firstId()))
  const href = createMemo(() => {
    const firstModel = first()
    const secondModel = second()
    if (!firstModel || !secondModel || firstModel.id === secondModel.id) return undefined
    return comparisonHref(modelRefFromCatalog(firstModel), modelRefFromCatalog(secondModel))
  })

  createEffect(() => {
    if (!secondId() || secondId() !== firstId()) return
    setSecondId("")
  })

  createEffect(() => {
    const url = href()
    if (!url || typeof window === "undefined") return
    window.location.href = url
  })

  return (
    <form
      data-component="compare-home-selector"
      aria-label="Model comparison selector"
      onSubmit={(event) => event.preventDefault()}
    >
      <CompareHomeSelect
        selected={first()}
        label="First model"
        expanded={activeSlot() === "first"}
        onOpen={() => setActiveSlot("first")}
      />
      <CompareHomeSelect
        selected={second()}
        label="Second model"
        expanded={activeSlot() === "second"}
        onOpen={() => setActiveSlot("second")}
      />
      <Show when={activeSlot()}>
        {(slot) => (
          <CompareModelSelectModal
            models={props.models}
            selected={activeSelected()}
            blockedId={activeBlockedId()}
            label={slot() === "first" ? "Choose first model" : "Choose second model"}
            onClose={() => setActiveSlot(undefined)}
            onSelect={(model) => {
              if (slot() === "first") setFirstId(model.id)
              if (slot() === "second") setSecondId(model.id)
              setActiveSlot(undefined)
            }}
          />
        )}
      </Show>
    </form>
  )
}

function CompareHomeSelect(props: {
  selected: ModelCatalogEntry | undefined
  label: string
  expanded: boolean
  onOpen: () => void
}) {
  return (
    <button
      type="button"
      data-slot="compare-home-select-panel"
      data-selected={props.selected ? "true" : undefined}
      aria-label={props.label}
      aria-haspopup="dialog"
      aria-expanded={props.expanded}
      onClick={props.onOpen}
    >
      <span data-slot="compare-home-select-copy">
        <span data-slot="compare-home-plus" aria-hidden="true">
          +
        </span>
        <Show when={props.selected}>{(model) => <ModelAvatar model={model()} size="tiny" />}</Show>
        <span data-slot="compare-home-select-name">{props.selected?.name ?? "Select a model"}</span>
      </span>
    </button>
  )
}

function CompareModelSelectModal(props: {
  models: ModelCatalogEntry[]
  selected: ModelCatalogEntry | undefined
  blockedId: string
  label: string
  onClose: () => void
  onSelect: (model: ModelCatalogEntry) => void
}) {
  let searchInput: HTMLInputElement | undefined
  const [search, setSearch] = createSignal("")
  const [previewId, setPreviewId] = createSignal(props.selected?.id ?? "")
  const availableModels = createMemo(() => props.models.filter((model) => model.id !== props.blockedId))
  const filteredModels = createMemo(() => {
    const terms = search().trim().toLowerCase().split(/\s+/).filter(Boolean)
    if (terms.length === 0) return availableModels()
    return availableModels().filter((model) => terms.every((term) => modelSearchText(model).includes(term)))
  })
  const preview = createMemo(
    () => filteredModels().find((model) => model.id === previewId()) ?? filteredModels()[0] ?? availableModels()[0],
  )

  createEffect(() => {
    const selected = props.selected
    const fallback = selected && selected.id !== props.blockedId ? selected.id : filteredModels()[0]?.id
    if (!fallback) return
    if (availableModels().some((model) => model.id === previewId())) return
    setPreviewId(fallback)
  })

  createEffect(() => {
    const models = filteredModels()
    if (models.some((model) => model.id === previewId())) return
    setPreviewId(models[0]?.id ?? "")
  })

  createEffect(() => {
    if (typeof window === "undefined") return
    window.requestAnimationFrame(() => searchInput?.focus())
  })

  return (
    <div
      data-component="compare-model-modal-scrim"
      role="presentation"
      onClick={props.onClose}
      onKeyDown={(event) => {
        if (event.key !== "Escape") return
        props.onClose()
      }}
    >
      <div
        data-component="compare-model-modal"
        role="dialog"
        aria-modal="true"
        aria-label={props.label}
        onClick={(event) => event.stopPropagation()}
      >
        <div data-slot="compare-model-modal-list">
          <label data-slot="compare-model-modal-search">
            <span data-slot="compare-model-modal-search-icon" aria-hidden="true" />
            <input
              ref={searchInput}
              value={search()}
              placeholder="Search models"
              aria-label="Search models"
              onInput={(event) => setSearch(event.currentTarget.value)}
            />
          </label>
          <div data-slot="compare-model-modal-results">
            <Show
              when={filteredModels().length > 0}
              fallback={
                <div data-slot="compare-model-modal-empty">
                  <strong>No models found</strong>
                  <span>Try another search.</span>
                </div>
              }
            >
              <For each={filteredModels()}>
                {(model) => (
                  <button
                    type="button"
                    data-slot="compare-model-modal-row"
                    data-active={preview()?.id === model.id ? "true" : undefined}
                    onPointerEnter={() => setPreviewId(model.id)}
                    onFocus={() => setPreviewId(model.id)}
                    onClick={() => props.onSelect(model)}
                  >
                    <span data-slot="compare-model-modal-row-main">
                      <ModelAvatar model={model} size="tiny" />
                      <span>{model.name}</span>
                    </span>
                    <Show when={isFreeModel(model)}>
                      <span data-slot="compare-model-modal-badge">Free</span>
                    </Show>
                  </button>
                )}
              </For>
            </Show>
          </div>
        </div>
        <div data-slot="compare-model-modal-divider" aria-hidden="true" />
        <Show when={preview()}>{(model) => <CompareModelDetail model={model()} />}</Show>
      </div>
    </div>
  )
}

