import { Resource } from "sst/resource"
import type { R2SqlData } from "../r2-sql"
import type { GeoStatAggregate } from "./geo"
import type { ModelStatAggregate } from "./model"
import {
  EXCLUDED_MODELS,
  FREE_MODELS,
  MODEL_AUTHOR_RULES,
  MODEL_NAME_MAX_LENGTH,
  MODEL_NAME_ALIASES,
  RETIRED_STAT_PROVIDERS,
  STEALTH_MODELS,
  statModel,
  statProvider,
} from "./model-normalization"
import type { ProviderStatAggregate } from "./provider"
import type { RetentionStatAggregate } from "./retention"
import {
  normalizeCountry,
  normalizeTier,
  periodKeyFor,
  startOfIsoWeek,
  startOfUtcDay,
  type StatBaseAggregate,
} from "./stat"

export type StatDimension = "model" | "provider" | "geo" | "geo_model"
export type StatsQuerySource = { namespace: string; table: string; dataset: string }
export type RetentionQuery = { cohortDates: string[]; query: string }
type StatsQueryFamily = "usage" | "geo"

const DAY_MS = 86_400_000
const WEEK_MS = 7 * DAY_MS
// The typed production stream began before the legacy backfill's original end
// boundary. Use one exclusive handoff so the overlapping rows are never counted
// from both sources.
const LIVE_SOURCE_START = "2026-08-11T10:57:48.186Z"

// R2 SQL results are cursor-paginated after aggregation. Separate usage and geo
// queries per day/week avoid combining costly distinct user/session aggregates
// with the high-cardinality geo dimensions.
export function buildStatsQueries(periodStart: Date, periodEnd: Date, input?: StatsQuerySource) {
  const source = input ?? {
    namespace: Resource.R2Sql.namespace,
    table: Resource.R2Sql.table,
    dataset: Resource.StatsSyncConfig.dataset,
  }
  return [...statPeriods("week", periodStart, periodEnd), ...statPeriods("day", periodStart, periodEnd)].flatMap(
    (period) => [buildStatsQuery(period, source, "usage"), buildStatsQuery(period, source, "geo")],
  )
}

export function buildRetentionQueries(periodStart: Date, periodEnd: Date, input?: StatsQuerySource): RetentionQuery[] {
  const source = input ?? {
    namespace: Resource.R2Sql.namespace,
    table: Resource.R2Sql.table,
    dataset: Resource.StatsSyncConfig.dataset,
  }
  const periods = retentionPeriods(periodStart, periodEnd)
  // Bound the user-level joins to one activity week and its return week.
  // Combining the entire display window makes full syncs much more expensive.
  return periods.map((period) => ({
    cohortDates: [period.start.toISOString().slice(0, 10)],
    query: buildRetentionQuery([period], source),
  }))
}

function buildRetentionQuery(
  periods: { start: Date; end: Date; returnStart: Date; returnEnd: Date }[],
  source: StatsQuerySource,
) {
  const first = periods[0]
  const last = periods.at(-1)!
  const scanStartValue = sqlString(first.start.toISOString())
  const scanEndValue = sqlString(last.returnEnd.toISOString())
  const ingestEndValue = sqlString(new Date(last.returnEnd.getTime() + DAY_MS).toISOString())
  const sourceTable = [source.namespace, source.table].map(sqlIdentifier).join(".")
  const activityWeeks = [
    ...new Map(
      periods.flatMap((period) => [period.start, period.returnStart]).map((date) => [date.toISOString(), date]),
    ).values(),
  ].toSorted((a, b) => a.getTime() - b.getTime())
  const activityWeekSql = `CASE
${activityWeeks
  .map(
    (date) =>
      `      WHEN started_at >= ${sqlString(date.toISOString())} AND started_at < ${sqlString(new Date(date.getTime() + WEEK_MS).toISOString())} THEN ${sqlString(date.toISOString().slice(0, 10))}`,
  )
  .join("\n")}
      ELSE null
    END`
  const cohortDates = periods.map((period) => sqlString(period.start.toISOString().slice(0, 10))).join(", ")
  const returnDates = periods.map((period) => sqlString(period.returnStart.toISOString().slice(0, 10))).join(", ")
  const returnCohortSql = `CASE activity_week
${periods
  .map(
    (period) =>
      `      WHEN ${sqlString(period.returnStart.toISOString().slice(0, 10))} THEN ${sqlString(period.start.toISOString().slice(0, 10))}`,
  )
  .join("\n")}
    END`

  return `
WITH normalized AS (
  SELECT
    ${activityWeekSql} AS activity_week,
    ${statModelSql("model_requested", "route_model")} AS model,
    COALESCE(NULLIF(route_model, ''), '') AS provider_model,
    COALESCE(NULLIF(provider_id, ''), '') AS raw_provider,
    COALESCE(NULLIF(user_id, ''), NULLIF(workspace_id, ''), NULLIF(service_api_key_id, '')) AS user_key
  FROM ${sourceTable}
  WHERE event_type = 'generation.completed'
    AND source IN ('inference', 'inference-legacy')
    AND (
      (source = 'inference-legacy' AND started_at < ${sqlString(LIVE_SOURCE_START)})
      OR (source = 'inference' AND started_at >= ${sqlString(LIVE_SOURCE_START)})
    )
    AND product = 'go'
    AND model_requested IS NOT NULL
    AND model_requested <> ''
    AND __ingest_ts >= ${scanStartValue}
    AND __ingest_ts < ${ingestEndValue}
    AND started_at >= ${scanStartValue}
    AND started_at < ${scanEndValue}
), filtered AS (
  SELECT
    activity_week,
    ${statProviderSql("model", "provider_model", "raw_provider")} AS provider,
    model,
    user_key
  FROM normalized
  WHERE activity_week IS NOT NULL
    AND user_key <> ''
    AND lower(model) NOT IN (${[...EXCLUDED_MODELS].map(sqlString).join(", ")})
), model_usage AS (
  SELECT
    activity_week AS cohort_date,
    user_key,
    provider,
    model,
    COUNT(*) AS model_requests
  FROM filtered
  WHERE activity_week IN (${cohortDates})
  GROUP BY activity_week, user_key, provider, model
), user_totals AS (
  SELECT
    cohort_date,
    user_key,
    SUM(model_requests) AS total_requests,
    MAX(model_requests) AS max_model_requests
  FROM model_usage
  GROUP BY cohort_date, user_key
), primary_models AS (
  SELECT model_usage.cohort_date, model_usage.user_key, model_usage.provider, model_usage.model
  FROM model_usage
  INNER JOIN user_totals ON model_usage.cohort_date = user_totals.cohort_date
    AND model_usage.user_key = user_totals.user_key
    AND model_usage.model_requests = user_totals.max_model_requests
  WHERE user_totals.total_requests >= 10
    AND CAST(model_usage.model_requests AS double) / NULLIF(user_totals.total_requests, 0) >= 0.8
), returned AS (
  SELECT
    ${returnCohortSql} AS cohort_date,
    user_key
  FROM filtered
  WHERE activity_week IN (${returnDates})
  GROUP BY ${returnCohortSql}, user_key
)
SELECT
  primary_models.cohort_date,
  ${sqlString(source.dataset)} AS dataset,
  'Go' AS tier,
  primary_models.provider,
  primary_models.model,
  COUNT(*) AS eligible_users,
  SUM(CASE WHEN returned.user_key IS NULL THEN 0 ELSE 1 END) AS retained_users
FROM primary_models
LEFT JOIN returned ON primary_models.user_key = returned.user_key
  AND primary_models.cohort_date = returned.cohort_date
GROUP BY primary_models.cohort_date, primary_models.provider, primary_models.model
LIMIT 10000
`
}

function buildStatsQuery(
  period: { grain: "day" | "week"; key: string; start: Date; end: Date },
  source: StatsQuerySource,
  family: StatsQueryFamily,
) {
  const periodStartValue = sqlString(period.start.toISOString())
  const periodEndValue = sqlString(period.end.toISOString())
  const ingestEndValue = sqlString(new Date(period.end.getTime() + DAY_MS).toISOString())
  const sourceTable = [source.namespace, source.table].map(sqlIdentifier).join(".")
  const sourceFreeTier = freeTierSql("model_tier", "model_requested")
  const dimensions =
    family === "usage"
      ? `CASE WHEN grouping(model) = 0 THEN 'model' ELSE 'provider' END AS dimension,
  tier,
  provider,
  CASE WHEN grouping(model) = 0 THEN model END AS model,
  CASE WHEN grouping(model) = 0 THEN COALESCE(MAX(NULLIF(provider_model, '')), '') END AS provider_model,
  null AS country,
  null AS continent`
      : `CASE WHEN grouping(model) = 0 THEN 'geo_model' ELSE 'geo' END AS dimension,
  tier,
  CASE WHEN grouping(model) = 0 THEN provider ELSE 'all' END AS provider,
  CASE WHEN grouping(model) = 0 THEN model ELSE 'all' END AS model,
  null AS provider_model,
  country,
  COALESCE(MAX(NULLIF(continent, '')), '') AS continent`
  const distinctColumns =
    family === "usage"
      ? `approx_distinct(session) AS sessions,
    approx_distinct(user_key) AS unique_users`
      : `0 AS sessions,
    0 AS unique_users`
  const groupingSets =
    family === "usage"
      ? `(tier, provider, model),
  (tier, provider)`
      : `(tier, country),
  (tier, provider, model, country)`
  const aggregateColumns = `
    ${distinctColumns},
    COUNT(*) AS requests,
    COALESCE(SUM(tokens_input), 0) AS input_tokens,
    COALESCE(SUM(tokens_output), 0) AS output_tokens,
    COALESCE(SUM(tokens_reasoning), 0) AS reasoning_tokens,
    COALESCE(SUM(tokens_cache_read), 0) AS cache_read_tokens,
    COALESCE(SUM(tokens_total), 0) AS total_tokens,
    COALESCE(SUM(cost_input_microcents), 0) AS input_cost_microcents,
    COALESCE(SUM(cost_output_microcents), 0) AS output_cost_microcents,
    COALESCE(SUM(cost_total_microcents), 0) AS total_cost_microcents,
    AVG(duration_ms) AS avg_duration_ms,
    null AS p50_duration_ms,
    null AS p95_duration_ms,
    AVG(ttfb_ms) AS avg_ttfb_ms,
    null AS p50_ttfb_ms,
    null AS p95_ttfb_ms,
    AVG(output_tps) AS avg_output_tps,
    SUM(CASE WHEN outcome = 'succeeded' THEN 1 ELSE 0 END) AS success_count,
    SUM(CASE WHEN outcome = 'failed' THEN 1 ELSE 0 END) AS error_count,
    COUNT(*) AS sample_count`

  return `
WITH normalized AS (
  SELECT
    model_requested AS raw_model,
    COALESCE(NULLIF(lower(model_tier), ''), '') AS raw_tier,
    ${statModelSql("model_requested", "route_model")} AS model,
    COALESCE(NULLIF(route_model, ''), '') AS provider_model,
    COALESCE(NULLIF(provider_id, ''), '') AS raw_provider,
    UPPER(COALESCE(NULLIF(country, ''), 'ZZ')) AS country,
    COALESCE(NULLIF(continent, ''), '') AS continent,
    session_id AS session,
    COALESCE(NULLIF(workspace_id, ''), '') AS workspace,
    COALESCE(NULLIF(service_api_key_id, ''), '') AS api_key,
    COALESCE(NULLIF(user_id, ''), '') AS user_id,
    outcome,
    duration_ms,
    time_to_first_token_ms AS ttfb_ms,
    CASE
      WHEN first_token_at IS NULL OR last_token_at IS NULL THEN null
      ELSE date_part('epoch', last_token_at) - date_part('epoch', first_token_at)
    END AS output_seconds,
    tokens_input,
    tokens_output,
    tokens_reasoning,
    tokens_cache_read,
    tokens_cache_write,
    cost_input AS cost_input_microcents,
    cost_output AS cost_output_microcents,
    cost_total AS cost_total_microcents
  FROM ${sourceTable}
  WHERE event_type = 'generation.completed'
    AND source IN ('inference', 'inference-legacy')
    AND (
      (source = 'inference-legacy' AND started_at < ${sqlString(LIVE_SOURCE_START)})
      OR (source = 'inference' AND started_at >= ${sqlString(LIVE_SOURCE_START)})
    )
    AND (product = 'go' OR (${sourceFreeTier}))
    AND model_requested IS NOT NULL
    AND model_requested <> ''
    AND __ingest_ts >= ${periodStartValue}
    AND __ingest_ts < ${ingestEndValue}
    AND started_at >= ${periodStartValue}
    AND started_at < ${periodEndValue}
), filtered AS (
  SELECT
    CASE
      WHEN ${freeTierSql("raw_tier", "raw_model")}
      THEN 'Free'
      ELSE 'Go'
    END AS tier,
    ${statProviderSql("model", "provider_model", "raw_provider")} AS provider,
    provider_model,
    model,
    country,
    continent,
    session,
    COALESCE(NULLIF(user_id, ''), NULLIF(workspace, ''), NULLIF(api_key, '')) AS user_key,
    outcome,
    duration_ms,
    ttfb_ms,
    CASE
      WHEN output_seconds < 0.1 THEN null
      ELSE CAST(tokens_output AS double) / output_seconds
    END AS output_tps,
    tokens_input,
    tokens_output,
    tokens_reasoning,
    tokens_cache_read,
    COALESCE(tokens_cache_read, 0) + COALESCE(tokens_cache_write, 0) + COALESCE(tokens_input, 0) + COALESCE(tokens_output, 0) AS tokens_total,
    cost_input_microcents,
    cost_output_microcents,
    cost_total_microcents
  FROM normalized
  WHERE lower(model) NOT IN (${[...EXCLUDED_MODELS].map(sqlString).join(", ")})
)
SELECT
  ${sqlString(period.grain)} AS grain,
  ${sqlString(period.key)} AS period_key,
  ${sqlString(source.dataset)} AS dataset,
  ${dimensions},
  ${aggregateColumns}
FROM filtered
GROUP BY GROUPING SETS (
  ${groupingSets}
)
`
}

export function toModelAggregate(data: R2SqlData): ModelStatAggregate[] {
  const model = statModel(data.model, data.provider_model)
  const provider = statProvider(model, data.provider_model, data.provider)
  if (!provider) return []

  return toStatBaseAggregate(data).flatMap((base) => [
    { ...base, provider, model, provider_model: data.provider_model || "" },
  ])
}

export function toProviderAggregate(data: R2SqlData): ProviderStatAggregate[] {
  return toStatBaseAggregate(data).flatMap((base) => [
    { ...base, provider: statProvider(data.model, data.provider_model, data.provider) || "unknown" },
  ])
}

export function toGeoAggregate(data: R2SqlData): GeoStatAggregate[] {
  return toStatBaseAggregate(data).flatMap((base) => [
    {
      ...base,
      provider: statProvider(data.model, data.provider_model, data.provider) || "all",
      model: statModel(data.model || "all", data.provider_model),
      country: normalizeCountry(data.country),
      continent: data.continent || "",
    },
  ])
}

export function toRetentionAggregate(data: R2SqlData): RetentionStatAggregate[] {
  if (!data.cohort_date || !data.model) return []
  return [
    {
      cohortDate: data.cohort_date,
      dataset: data.dataset || Resource.StatsSyncConfig.dataset,
      tier: data.tier || "all",
      provider: statProvider(data.model, "", data.provider) || "unknown",
      model: statModel(data.model, undefined),
      eligibleUsers: integer(data, "eligible_users"),
      retainedUsers: integer(data, "retained_users"),
    },
  ]
}

function toStatBaseAggregate(data: R2SqlData): StatBaseAggregate[] {
  const grain = data.grain === "day" || data.grain === "week" ? data.grain : undefined
  if (!grain || !data.period_key) return []

  return [
    {
      grain,
      period_key: data.period_key,
      dataset: data.dataset || Resource.StatsSyncConfig.dataset,
      tier: normalizeTier(data.tier || "unknown"),
      sessions: integer(data, "sessions"),
      requests: integer(data, "requests"),
      unique_users: integer(data, "unique_users"),
      input_tokens: integer(data, "input_tokens"),
      output_tokens: integer(data, "output_tokens"),
      reasoning_tokens: integer(data, "reasoning_tokens"),
      cache_read_tokens: integer(data, "cache_read_tokens"),
      total_tokens: integer(data, "total_tokens"),
      input_cost_microcents: integer(data, "input_cost_microcents"),
      output_cost_microcents: integer(data, "output_cost_microcents"),
      total_cost_microcents: integer(data, "total_cost_microcents"),
      avg_duration_ms: nullableNumber(data, "avg_duration_ms"),
      p50_duration_ms: nullableInteger(data, "p50_duration_ms"),
      p95_duration_ms: nullableInteger(data, "p95_duration_ms"),
      avg_ttfb_ms: nullableNumber(data, "avg_ttfb_ms"),
      p50_ttfb_ms: nullableInteger(data, "p50_ttfb_ms"),
      p95_ttfb_ms: nullableInteger(data, "p95_ttfb_ms"),
      avg_output_tps: nullableNumber(data, "avg_output_tps"),
      success_count: integer(data, "success_count"),
      error_count: integer(data, "error_count"),
      sample_count: integer(data, "sample_count"),
    },
  ]
}

function integer(data: R2SqlData, key: string) {
  return Math.round(number(data, key))
}

function nullableNumber(data: R2SqlData, key: string) {
  if (data[key] === undefined || data[key] === "") return null
  return Number(number(data, key).toFixed(2))
}

function nullableInteger(data: R2SqlData, key: string) {
  if (data[key] === undefined || data[key] === "") return null
  return Math.round(number(data, key))
}

function number(data: R2SqlData, key: string) {
  const value = Number(data[key])
  return Number.isFinite(value) ? value : 0
}

function sqlIdentifier(value: string) {
  return `"${value.replace(/"/g, '""')}"`
}

function sqlString(value: string) {
  return `'${value.replace(/'/g, "''")}'`
}

function statPeriods(grain: "day" | "week", periodStart: Date, periodEnd: Date) {
  const interval = grain === "day" ? DAY_MS : WEEK_MS
  const first = grain === "day" ? startOfUtcDay(periodStart) : startOfIsoWeek(periodStart)
  const count = Math.max(0, Math.ceil((periodEnd.getTime() - first.getTime()) / interval))
  return Array.from({ length: count }, (_, index) => {
    const start = new Date(first.getTime() + index * interval)
    return {
      grain,
      key: periodKeyFor(grain, start),
      start,
      end: new Date(Math.min(start.getTime() + interval, periodEnd.getTime())),
    }
  })
}

function retentionPeriods(periodStart: Date, periodEnd: Date) {
  const first = startOfIsoWeek(periodStart)
  const completeEnd = startOfIsoWeek(periodEnd)
  const count = Math.max(0, Math.floor((completeEnd.getTime() - first.getTime()) / WEEK_MS) - 1)
  return Array.from({ length: count }, (_, index) => {
    const start = new Date(first.getTime() + index * WEEK_MS)
    const end = new Date(start.getTime() + WEEK_MS)
    return { start, end, returnStart: end, returnEnd: new Date(end.getTime() + WEEK_MS) }
  })
}

function statModelSql(model: string, providerModel: string) {
  const normalized = `regexp_replace(CASE
      WHEN lower(${model}) = 'big-pickle' THEN regexp_replace(NULLIF(${providerModel}, ''), '^.*/', '')
      ELSE ${model}
    END, '(-free|:free|:global)+$', '')`
  const value = `CASE
${Object.entries(MODEL_NAME_ALIASES)
  .map(([from, to]) => `      WHEN lower(${normalized}) = ${sqlString(from)} THEN ${sqlString(to)}`)
  .join("\n")}
      ELSE ${normalized}
    END`
  return `CASE
      WHEN length(${value}) > ${MODEL_NAME_MAX_LENGTH} THEN 'unknown'
      ELSE COALESCE(NULLIF(${value}, ''), 'unknown')
    END`
}

function freeTierSql(tier: string, model: string) {
  return `lower(COALESCE(${tier}, '')) = 'free'
        OR lower(${model}) IN (${[...FREE_MODELS].map(sqlString).join(", ")})
        OR lower(${model}) LIKE '%-free'
        OR lower(${model}) LIKE '%-free:global'`
}

function statProviderSql(model: string, providerModel: string, provider: string) {
  return `CASE
      WHEN lower(${model}) IN (${[...STEALTH_MODELS].map(sqlString).join(", ")}) THEN 'unknown'
${MODEL_AUTHOR_RULES.map((item) => `      WHEN strpos(lower(${providerModel}), ${sqlString(item.match)}) > 0 THEN ${sqlString(item.author)}`).join("\n")}
${MODEL_AUTHOR_RULES.map((item) => `      WHEN strpos(lower(${model}), ${sqlString(item.match)}) > 0 THEN ${sqlString(item.author)}`).join("\n")}
      WHEN ${provider} <> '' AND lower(${provider}) NOT IN (${RETIRED_STAT_PROVIDERS.map(sqlString).join(", ")}) THEN ${provider}
      ELSE 'unknown'
    END`
}

export const MODEL_AUTHOR_RULES = [
  { match: "claude", author: "anthropic" },
  { match: "gemini", author: "google" },
  { match: "deepseek", author: "deepseek" },
  { match: "glm", author: "zhipu" },
  { match: "gpt", author: "openai" },
  { match: "grok", author: "xai" },
  { match: "hy3", author: "tencent" },
  { match: "hy4", author: "tencent" },
  { match: "kimi", author: "moonshot" },
  { match: "mimo", author: "xiaomi" },
  { match: "minimax", author: "minimax" },
  { match: "muse-spark", author: "meta" },
  { match: "nemotron", author: "nvidia" },
  { match: "qwen", author: "qwen" },
] as const
export const EXCLUDED_MODELS = new Set(["alpha-gpt-next"])
export const STEALTH_MODELS = new Set(["omen-alpha", "space-bunny", "union-alpha"])
export const FREE_MODELS = new Set(["gpt-5-nano", "grok-code", "big-pickle"])
export const MODEL_NAME_MAX_LENGTH = 256
export const MODEL_NAME_ALIASES: Record<string, string> = {
  "deepseek-flash": "deepseek-v4.1-flash",
  "deepseek-v4-flash-0731": "deepseek-v4-flash",
  "deepseek-v4-flash-dsv4-flash-final-rnaovd": "deepseek-v4-flash",
  "opencode-go/union-alpha": "union-alpha",
  "opencode/union-alpha": "union-alpha",
  "ox-alpha": "glm-5.3-flash",
  "x-preview-f": "glm-5.3-flash",
  "xiaomi/mimo-v2.5": "mimo-v2.5",
}
export const RETIRED_STAT_MODELS = ["big-pickle", ...Object.keys(MODEL_NAME_ALIASES)]
export const RETIRED_STAT_PROVIDERS = ["opencode"]

export function normalizeInferenceModel(value: string | undefined) {
  return (value || "unknown").toLowerCase().replace(/(-free|:free|:global)+$/, "") || "unknown"
}

export function modelAuthor(value: string | undefined) {
  const model = normalizeInferenceModel(value).toLowerCase()
  if (EXCLUDED_MODELS.has(model)) return undefined

  return MODEL_AUTHOR_RULES.find((item) => model.includes(item.match))?.author ?? "unknown"
}

export function statModel(model: string | undefined, providerModel: string | undefined) {
  const normalized = normalizeInferenceModel(model)
  const resolved = normalized === "big-pickle" ? normalizeInferenceModel(providerModel?.split("/").at(-1)) : normalized
  const value = MODEL_NAME_ALIASES[resolved.toLowerCase()] ?? resolved
  return value.length > MODEL_NAME_MAX_LENGTH ? "unknown" : value
}

export function statProvider(
  model: string | undefined,
  providerModel: string | undefined,
  provider: string | undefined,
) {
  const normalized = statModel(model, providerModel)
  if (STEALTH_MODELS.has(normalized)) return "unknown"

  const modelAuthorValue = modelAuthor(normalized)
  if (!modelAuthorValue) return undefined

  const providerModelAuthor = modelAuthor(providerModel)
  if (providerModelAuthor && providerModelAuthor !== "unknown") return providerModelAuthor
  if (modelAuthorValue !== "unknown") return modelAuthorValue
  if (provider && !RETIRED_STAT_PROVIDERS.includes(provider.toLowerCase())) return provider
  return modelAuthorValue
}

import { and, asc, eq, inArray, max, or } from "drizzle-orm"
import { Effect, Layer } from "effect"
import * as Context from "effect/Context"
import { DatabaseError, DrizzleClient } from "../database"
import { modelStat } from "../database/schema"
import { RETIRED_STAT_MODELS, RETIRED_STAT_PROVIDERS } from "./model-normalization"
import {
  chunks,
  collapseRows,
  DATA_SITE_TIERS,
  inserted,
  isMissingUniqueUsersColumn,
  omitUniqueUsers,
  rankBy,
  statPeriodKey,
  statRowScope,
  synthesizeAllTierRows,
  toStatBaseRow,
  UPSERT_CHUNK_SIZE,
  type StatBaseAggregate,
} from "./stat"

export type ModelStatRow = typeof modelStat.$inferInsert
export type ModelStatAggregate = StatBaseAggregate & { provider: string; model: string; provider_model: string }

export type ModelStatMetric = {
  periodKey: string
  updatedAt: Date
  tier: string
  provider: string
  model: string
  sessions: number
  uniqueUsers: number
  inputTokens: number
  outputTokens: number
  reasoningTokens: number
  cacheReadTokens: number
  totalTokens: number
  inputCostMicrocents: number
  outputCostMicrocents: number
  totalCostMicrocents: number
}

export declare namespace ModelStatRepo {
  export interface Service {
    readonly listDaily: () => Effect.Effect<ModelStatMetric[], DatabaseError>
    readonly lastSyncedAt: () => Effect.Effect<Date | null, DatabaseError>
    readonly upsert: (rows: ModelStatRow[]) => Effect.Effect<void, DatabaseError>
    readonly deleteRetiredDimensions: (rows: ModelStatRow[]) => Effect.Effect<void, DatabaseError>
  }
}

export class ModelStatRepo extends Context.Service<ModelStatRepo, ModelStatRepo.Service>()(
  "@opencode/stats/ModelStatRepo",
) {
  static readonly layer: Layer.Layer<ModelStatRepo, never, DrizzleClient> = Layer.effect(
    ModelStatRepo,
    Effect.gen(function* () {
      const db = yield* DrizzleClient

      const listDaily = Effect.fn("ModelStatRepo.listDaily")(function* () {
        return yield* Effect.tryPromise({
          try: async () => {
            try {
              return await db
                .select({
                  periodKey: modelStat.period_key,
                  updatedAt: modelStat.updated_at,
                  tier: modelStat.tier,
                  provider: modelStat.provider,
                  model: modelStat.model,
                  sessions: modelStat.sessions,
                  uniqueUsers: modelStat.unique_users,
                  inputTokens: modelStat.input_tokens,
                  outputTokens: modelStat.output_tokens,
                  reasoningTokens: modelStat.reasoning_tokens,
                  cacheReadTokens: modelStat.cache_read_tokens,
                  totalTokens: modelStat.total_tokens,
                  inputCostMicrocents: modelStat.input_cost_microcents,
                  outputCostMicrocents: modelStat.output_cost_microcents,
                  totalCostMicrocents: modelStat.total_cost_microcents,
                })
                .from(modelStat)
                .where(modelDailyScope())
                .orderBy(asc(modelStat.period_key))
            } catch (cause) {
              if (!isMissingUniqueUsersColumn(cause)) throw cause
              return (
                await db
                  .select({
                    periodKey: modelStat.period_key,
                    updatedAt: modelStat.updated_at,
                    tier: modelStat.tier,
                    provider: modelStat.provider,
                    model: modelStat.model,
                    sessions: modelStat.sessions,
                    inputTokens: modelStat.input_tokens,
                    outputTokens: modelStat.output_tokens,
                    reasoningTokens: modelStat.reasoning_tokens,
                    cacheReadTokens: modelStat.cache_read_tokens,
                    totalTokens: modelStat.total_tokens,
                    inputCostMicrocents: modelStat.input_cost_microcents,
                    outputCostMicrocents: modelStat.output_cost_microcents,
                    totalCostMicrocents: modelStat.total_cost_microcents,
                  })
                  .from(modelStat)
                  .where(modelDailyScope())
                  .orderBy(asc(modelStat.period_key))
              ).map((row) => ({ ...row, uniqueUsers: 0 }))
            }
          },
          catch: (cause) => DatabaseError.make({ cause }),
        })
      })

      const lastSyncedAt = Effect.fn("ModelStatRepo.lastSyncedAt")(function* () {
        const result = yield* Effect.tryPromise({
          try: () => db.select({ value: max(modelStat.updated_at) }).from(modelStat),
          catch: (cause) => DatabaseError.make({ cause }),
        })
        return result[0]?.value ?? null
      })

      const upsert = Effect.fn("ModelStatRepo.upsert")(function* (rows: ModelStatRow[]) {
        yield* Effect.forEach(
          chunks(rows, UPSERT_CHUNK_SIZE),
          (chunk) =>
            Effect.tryPromise({
              try: async () => {
                try {
                  return await upsertModelChunk(chunk, true)
                } catch (cause) {
                  if (!isMissingUniqueUsersColumn(cause)) throw cause
                  return upsertModelChunk(chunk, false)
                }
              },
              catch: (cause) => DatabaseError.make({ cause }),
            }),
          { discard: true },
        )
      })

      function upsertModelChunk(chunk: ModelStatRow[], includeUniqueUsers: boolean) {
        return db
          .insert(modelStat)
          .values(includeUniqueUsers ? chunk : omitUniqueUsers(chunk))
          .onDuplicateKeyUpdate({
            set: {
              provider_model: inserted("provider_model"),
              sessions: inserted("sessions"),
              requests: inserted("requests"),
              ...(includeUniqueUsers ? { unique_users: inserted("unique_users") } : {}),
              input_tokens: inserted("input_tokens"),
              output_tokens: inserted("output_tokens"),
              reasoning_tokens: inserted("reasoning_tokens"),
              cache_read_tokens: inserted("cache_read_tokens"),
              total_tokens: inserted("total_tokens"),
              input_cost_microcents: inserted("input_cost_microcents"),
              output_cost_microcents: inserted("output_cost_microcents"),
              total_cost_microcents: inserted("total_cost_microcents"),
              avg_duration_ms: inserted("avg_duration_ms"),
              p50_duration_ms: inserted("p50_duration_ms"),
              p95_duration_ms: inserted("p95_duration_ms"),
              avg_ttfb_ms: inserted("avg_ttfb_ms"),
              p50_ttfb_ms: inserted("p50_ttfb_ms"),
              p95_ttfb_ms: inserted("p95_ttfb_ms"),
              avg_output_tps: inserted("avg_output_tps"),
              success_count: inserted("success_count"),
              error_count: inserted("error_count"),
              sample_count: inserted("sample_count"),
              rank_by_tokens: inserted("rank_by_tokens"),
              rank_by_requests: inserted("rank_by_requests"),
              rank_by_cost: inserted("rank_by_cost"),
            },
          })
      }

      const deleteRetiredDimensions = Effect.fn("ModelStatRepo.deleteRetiredDimensions")(function* (
        rows: ModelStatRow[],
      ) {
        const scope = statRowScope(rows)
        if (!scope) return

        yield* Effect.tryPromise({
          try: () =>
            db
              .delete(modelStat)
              .where(
                and(
                  inArray(modelStat.grain, scope.grains),
                  inArray(modelStat.period_key, scope.periodKeys),
                  inArray(modelStat.dataset, scope.datasets),
                  inArray(modelStat.client, scope.clients),
                  inArray(modelStat.source, scope.sources),
                  or(
                    inArray(modelStat.provider, RETIRED_STAT_PROVIDERS),
                    inArray(modelStat.model, RETIRED_STAT_MODELS),
                    and(eq(modelStat.provider, "unknown"), eq(modelStat.model, "hy4-preview")),
                  ),
                ),
              ),
          catch: (cause) => DatabaseError.make({ cause }),
        })
      })

      return ModelStatRepo.of({ listDaily, lastSyncedAt, upsert, deleteRetiredDimensions })
    }),
  )
}

function modelDailyScope() {
  return and(
    eq(modelStat.grain, "day"),
    eq(modelStat.client, "all"),
    eq(modelStat.source, "all"),
    inArray(modelStat.tier, DATA_SITE_TIERS),
  )
}

export function rowsFromAggregates(aggregates: ModelStatAggregate[]) {
  return rankRows([
    ...synthesizeAllTierRows(
      collapseRows(aggregates.filter((item) => item.grain === "week").map(toRow), dimensionKey),
      dimensionKey,
    ),
    ...synthesizeAllTierRows(
      collapseRows(aggregates.filter((item) => item.grain === "day").map(toRow), dimensionKey),
      dimensionKey,
    ),
  ])
}

function toRow(data: ModelStatAggregate): ModelStatRow {
  return {
    ...toStatBaseRow(data),
    provider: data.provider,
    model: data.model,
    provider_model: data.provider_model,
  }
}

function rankRows(rows: ModelStatRow[]) {
  return Object.values(
    rows.reduce<Record<string, ModelStatRow[]>>((result, row) => {
      const key = statPeriodKey(row)
      result[key] = [...(result[key] ?? []), row]
      return result
    }, {}),
  ).flatMap((group) => {
    const tokenRanks = rankBy(group, (row) => row.total_tokens ?? 0)
    const requestRanks = rankBy(group, (row) => row.requests ?? 0)
    const costRanks = rankBy(group, (row) => row.total_cost_microcents ?? 0)
    return group.map((row) => ({
      ...row,
      rank_by_tokens: tokenRanks.get(row) ?? null,
      rank_by_requests: requestRanks.get(row) ?? null,
      rank_by_cost: costRanks.get(row) ?? null,
    }))
  })
}

function dimensionKey(row: ModelStatRow) {
  return [row.provider, row.model].join("\u0000")
}

import { and, asc, eq, inArray } from "drizzle-orm"
import { Effect, Layer } from "effect"
import * as Context from "effect/Context"
import { DatabaseError, DrizzleClient } from "../database"
import { providerStat } from "../database/schema"
import { RETIRED_STAT_PROVIDERS } from "./model-normalization"
import {
  chunks,
  collapseRows,
  DATA_SITE_TIERS,
  inserted,
  isMissingUniqueUsersColumn,
  omitUniqueUsers,
  rankRowsWithMarketShare,
  statRowScope,
  synthesizeAllTierRows,
  toStatBaseRow,
  UPSERT_CHUNK_SIZE,
  type StatBaseAggregate,
} from "./stat"

export type ProviderStatRow = typeof providerStat.$inferInsert
export type ProviderStatAggregate = StatBaseAggregate & { provider: string }
export type ProviderStatMetric = {
  periodKey: string
  updatedAt: Date
  tier: string
  provider: string
  totalTokens: number
}

export declare namespace ProviderStatRepo {
  export interface Service {
    readonly listDaily: () => Effect.Effect<ProviderStatMetric[], DatabaseError>
    readonly listByPeriod: (opts: {
      readonly grain: string
      readonly periodKey: string
      readonly dataset?: string
      readonly tier?: string
      readonly client?: string
      readonly source?: string
    }) => Effect.Effect<ProviderStatRow[], DatabaseError>
    readonly upsert: (rows: ProviderStatRow[]) => Effect.Effect<void, DatabaseError>
    readonly deleteRetiredDimensions: (rows: ProviderStatRow[]) => Effect.Effect<void, DatabaseError>
  }
}

export class ProviderStatRepo extends Context.Service<ProviderStatRepo, ProviderStatRepo.Service>()(
  "@opencode/stats/ProviderStatRepo",
) {
  static readonly layer: Layer.Layer<ProviderStatRepo, never, DrizzleClient> = Layer.effect(
    ProviderStatRepo,
    Effect.gen(function* () {
      const db = yield* DrizzleClient

      const listDaily = Effect.fn("ProviderStatRepo.listDaily")(function* () {
        return yield* Effect.tryPromise({
          try: () =>
            db
              .select({
                periodKey: providerStat.period_key,
                updatedAt: providerStat.updated_at,
                tier: providerStat.tier,
                provider: providerStat.provider,
                totalTokens: providerStat.total_tokens,
              })
              .from(providerStat)
              .where(
                and(
                  eq(providerStat.grain, "day"),
                  eq(providerStat.client, "all"),
                  eq(providerStat.source, "all"),
                  inArray(providerStat.tier, DATA_SITE_TIERS),
                ),
              )
              .orderBy(asc(providerStat.period_key)),
          catch: (cause) => DatabaseError.make({ cause }),
        })
      })

      const listByPeriod = Effect.fn("ProviderStatRepo.listByPeriod")(function* (opts: {
        readonly grain: string
        readonly periodKey: string
        readonly dataset?: string
        readonly tier?: string
        readonly client?: string
        readonly source?: string
      }) {
        return yield* Effect.tryPromise({
          try: () =>
            db
              .select()
              .from(providerStat)
              .where(
                and(
                  eq(providerStat.grain, opts.grain),
                  eq(providerStat.period_key, opts.periodKey),
                  eq(providerStat.dataset, opts.dataset ?? "zen"),
                  eq(providerStat.tier, opts.tier ?? "all"),
                  eq(providerStat.client, opts.client ?? "all"),
                  eq(providerStat.source, opts.source ?? "all"),
                ),
              ),
          catch: (cause) => DatabaseError.make({ cause }),
        })
      })

      const upsert = Effect.fn("ProviderStatRepo.upsert")(function* (rows: ProviderStatRow[]) {
        yield* Effect.forEach(
          chunks(rows, UPSERT_CHUNK_SIZE),
          (chunk) =>
            Effect.tryPromise({
              try: async () => {
                try {
                  return await upsertProviderChunk(chunk, true)
                } catch (cause) {
                  if (!isMissingUniqueUsersColumn(cause)) throw cause
                  return upsertProviderChunk(chunk, false)
                }
              },
              catch: (cause) => DatabaseError.make({ cause }),
            }),
          { discard: true },
        )
      })

      function upsertProviderChunk(chunk: ProviderStatRow[], includeUniqueUsers: boolean) {
        return db
          .insert(providerStat)
          .values(includeUniqueUsers ? chunk : omitUniqueUsers(chunk))
          .onDuplicateKeyUpdate({
            set: {
              sessions: inserted("sessions"),
              requests: inserted("requests"),
              ...(includeUniqueUsers ? { unique_users: inserted("unique_users") } : {}),
              input_tokens: inserted("input_tokens"),
              output_tokens: inserted("output_tokens"),
              reasoning_tokens: inserted("reasoning_tokens"),
              cache_read_tokens: inserted("cache_read_tokens"),
              total_tokens: inserted("total_tokens"),
              input_cost_microcents: inserted("input_cost_microcents"),
              output_cost_microcents: inserted("output_cost_microcents"),
              total_cost_microcents: inserted("total_cost_microcents"),
              avg_duration_ms: inserted("avg_duration_ms"),
              p50_duration_ms: inserted("p50_duration_ms"),
              p95_duration_ms: inserted("p95_duration_ms"),
              avg_ttfb_ms: inserted("avg_ttfb_ms"),
              p50_ttfb_ms: inserted("p50_ttfb_ms"),
              p95_ttfb_ms: inserted("p95_ttfb_ms"),
              avg_output_tps: inserted("avg_output_tps"),
              success_count: inserted("success_count"),
              error_count: inserted("error_count"),
              sample_count: inserted("sample_count"),
              market_share_tokens: inserted("market_share_tokens"),
              market_share_requests: inserted("market_share_requests"),
              market_share_sessions: inserted("market_share_sessions"),
              rank_by_tokens: inserted("rank_by_tokens"),
              rank_by_requests: inserted("rank_by_requests"),
              rank_by_sessions: inserted("rank_by_sessions"),
              rank_by_cost: inserted("rank_by_cost"),
            },
          })
      }

      const deleteRetiredDimensions = Effect.fn("ProviderStatRepo.deleteRetiredDimensions")(function* (
        rows: ProviderStatRow[],
      ) {
        const scope = statRowScope(rows)
        if (!scope) return

        yield* Effect.tryPromise({
          try: () =>
            db
              .delete(providerStat)
              .where(
                and(
                  inArray(providerStat.grain, scope.grains),
                  inArray(providerStat.period_key, scope.periodKeys),
                  inArray(providerStat.dataset, scope.datasets),
                  inArray(providerStat.client, scope.clients),
                  inArray(providerStat.source, scope.sources),
                  inArray(providerStat.provider, RETIRED_STAT_PROVIDERS),
                ),
              ),
          catch: (cause) => DatabaseError.make({ cause }),
        })
      })

      return ProviderStatRepo.of({ listDaily, listByPeriod, upsert, deleteRetiredDimensions })
    }),
  )
}

export function rowsFromAggregates(aggregates: ProviderStatAggregate[]) {
  return rankRowsWithMarketShare([
    ...synthesizeAllTierRows(
      collapseRows(aggregates.filter((item) => item.grain === "week").map(toRow), dimensionKey),
      dimensionKey,
    ),
    ...synthesizeAllTierRows(
      collapseRows(aggregates.filter((item) => item.grain === "day").map(toRow), dimensionKey),
      dimensionKey,
    ),
  ])
}

function toRow(data: ProviderStatAggregate): ProviderStatRow {
  return {
    ...toStatBaseRow(data),
    provider: data.provider,
  }
}

function dimensionKey(row: ProviderStatRow) {
  return row.provider
}

import { and, eq, inArray } from "drizzle-orm"
import { Context, Effect, Layer } from "effect"
import { DatabaseError, DrizzleClient } from "../database"
import { modelRetention } from "../database/schema"
import { chunks, UPSERT_CHUNK_SIZE } from "./stat"

export type RetentionStatRow = typeof modelRetention.$inferInsert
export type RetentionStatAggregate = {
  cohortDate: string
  dataset: string
  tier: string
  provider: string
  model: string
  eligibleUsers: number
  retainedUsers: number
}

export declare namespace RetentionStatRepo {
  export interface Service {
    readonly available: () => Effect.Effect<boolean, DatabaseError>
    readonly replace: (
      rows: RetentionStatRow[],
      scope: { cohortDates: string[]; dataset: string; tier: string },
    ) => Effect.Effect<void, DatabaseError>
  }
}

export class RetentionStatRepo extends Context.Service<RetentionStatRepo, RetentionStatRepo.Service>()(
  "@opencode/stats/RetentionStatRepo",
) {
  static readonly layer: Layer.Layer<RetentionStatRepo, never, DrizzleClient> = Layer.effect(
    RetentionStatRepo,
    Effect.gen(function* () {
      const db = yield* DrizzleClient

      const available = Effect.fn("RetentionStatRepo.available")(function* () {
        return yield* Effect.tryPromise({
          try: async () => {
            try {
              await db.select({ id: modelRetention.id }).from(modelRetention).limit(1)
              return true
            } catch (cause) {
              if (isMissingRetentionTable(cause)) return false
              throw cause
            }
          },
          catch: (cause) => DatabaseError.make({ cause }),
        })
      })

      const replace = Effect.fn("RetentionStatRepo.replace")(function* (
        rows: RetentionStatRow[],
        scope: { cohortDates: string[]; dataset: string; tier: string },
      ) {
        if (scope.cohortDates.length === 0) return

        yield* Effect.tryPromise({
          try: () =>
            db
              .delete(modelRetention)
              .where(
                and(
                  inArray(modelRetention.cohort_date, scope.cohortDates),
                  eq(modelRetention.dataset, scope.dataset),
                  eq(modelRetention.tier, scope.tier),
                ),
              ),
          catch: (cause) => DatabaseError.make({ cause }),
        })
        yield* Effect.forEach(
          chunks(rows, UPSERT_CHUNK_SIZE),
          (chunk) =>
            Effect.tryPromise({
              try: () => db.insert(modelRetention).values(chunk),
              catch: (cause) => DatabaseError.make({ cause }),
            }),
          { discard: true },
        )
      })

      return RetentionStatRepo.of({ available, replace })
    }),
  )
}

export function rowsFromAggregates(aggregates: RetentionStatAggregate[]): RetentionStatRow[] {
  return aggregates.map((row) => ({
    cohort_date: row.cohortDate,
    dataset: row.dataset,
    tier: row.tier,
    provider: row.provider,
    model: row.model,
    eligible_users: row.eligibleUsers,
    retained_users: row.retainedUsers,
  }))
}

export function isMissingRetentionTable(cause: unknown): boolean {
  const text = errorText(cause).toLowerCase()
  return text.includes("model_retention") && text.includes("exist")
}

function errorText(cause: unknown): string {
  if (cause instanceof Error) return `${cause.message} ${errorText((cause as { cause?: unknown }).cause)}`
  if (typeof cause === "object" && cause)
    return Object.values(cause as Record<string, unknown>)
      .map(errorText)
      .join(" ")
  return String(cause)
}

import { sql } from "drizzle-orm"

export const UPSERT_CHUNK_SIZE = 500
export const DATA_SITE_TIERS = ["Go", "go", "Free", "free"]
const DAY_MS = 86_400_000

export type StatGrain = "day" | "week"

export type StatBaseAggregate = {
  grain: StatGrain
  period_key: string
  dataset: string
  tier: string
  sessions: number
  requests: number
  unique_users: number
  input_tokens: number
  output_tokens: number
  reasoning_tokens: number
  cache_read_tokens: number
  total_tokens: number
  input_cost_microcents: number
  output_cost_microcents: number
  total_cost_microcents: number
  avg_duration_ms: number | null
  p50_duration_ms: number | null
  p95_duration_ms: number | null
  avg_ttfb_ms: number | null
  p50_ttfb_ms: number | null
  p95_ttfb_ms: number | null
  avg_output_tps: number | null
  success_count: number
  error_count: number
  sample_count: number
}

export type StatBaseRow = {
  grain: string
  period_key: string
  dataset?: string
  tier?: string
  client?: string
  source?: string
  sessions?: number
  requests?: number
  unique_users?: number
  input_tokens?: number
  output_tokens?: number
  reasoning_tokens?: number
  cache_read_tokens?: number
  total_tokens?: number
  input_cost_microcents?: number
  output_cost_microcents?: number
  total_cost_microcents?: number
  avg_duration_ms?: number | null
  p50_duration_ms?: number | null
  p95_duration_ms?: number | null
  avg_ttfb_ms?: number | null
  p50_ttfb_ms?: number | null
  p95_ttfb_ms?: number | null
  avg_output_tps?: number | null
  success_count?: number
  error_count?: number
  sample_count?: number
}

export function toStatBaseRow(data: StatBaseAggregate) {
  return {
    grain: data.grain,
    period_key: data.period_key,
    dataset: data.dataset,
    tier: data.tier,
    client: "all",
    source: "all",
    sessions: data.sessions,
    requests: data.requests,
    unique_users: data.unique_users,
    input_tokens: data.input_tokens,
    output_tokens: data.output_tokens,
    reasoning_tokens: data.reasoning_tokens,
    cache_read_tokens: data.cache_read_tokens,
    total_tokens: data.total_tokens,
    input_cost_microcents: data.input_cost_microcents,
    output_cost_microcents: data.output_cost_microcents,
    total_cost_microcents: data.total_cost_microcents,
    avg_duration_ms: data.avg_duration_ms,
    p50_duration_ms: data.p50_duration_ms,
    p95_duration_ms: data.p95_duration_ms,
    avg_ttfb_ms: data.avg_ttfb_ms,
    p50_ttfb_ms: data.p50_ttfb_ms,
    p95_ttfb_ms: data.p95_ttfb_ms,
    avg_output_tps: data.avg_output_tps,
    success_count: data.success_count,
    error_count: data.error_count,
    sample_count: data.sample_count,
  }
}

export function synthesizeAllTierRows<T extends StatBaseRow>(rows: T[], dimensionKey: (row: T) => string) {
  return [
    ...rows,
    ...Object.values(
      rows.reduce<Record<string, T>>((result, row) => {
        const key = [row.grain, row.period_key, row.dataset, row.client, row.source, dimensionKey(row)].join("\u0000")
        result[key] = result[key] ? combineRows(result[key], row) : { ...row, tier: "all" }
        return result
      }, {}),
    ),
  ]
}

export function collapseRows<T extends StatBaseRow>(rows: T[], dimensionKey: (row: T) => string) {
  return Object.values(
    rows.reduce<Record<string, T>>((result, row) => {
      const key = [row.grain, row.period_key, row.dataset, row.tier, row.client, row.source, dimensionKey(row)].join(
        "\u0000",
      )
      result[key] = result[key] ? combineRows(result[key], row) : row
      return result
    }, {}),
  )
}

export function combineRows<T extends StatBaseRow>(left: T, right: T): T {
  return {
    ...left,
    sessions: (left.sessions ?? 0) + (right.sessions ?? 0),
    requests: (left.requests ?? 0) + (right.requests ?? 0),
    unique_users: (left.unique_users ?? 0) + (right.unique_users ?? 0),
    input_tokens: (left.input_tokens ?? 0) + (right.input_tokens ?? 0),
    output_tokens: (left.output_tokens ?? 0) + (right.output_tokens ?? 0),
    reasoning_tokens: (left.reasoning_tokens ?? 0) + (right.reasoning_tokens ?? 0),
    cache_read_tokens: (left.cache_read_tokens ?? 0) + (right.cache_read_tokens ?? 0),
    total_tokens: (left.total_tokens ?? 0) + (right.total_tokens ?? 0),
    input_cost_microcents: (left.input_cost_microcents ?? 0) + (right.input_cost_microcents ?? 0),
    output_cost_microcents: (left.output_cost_microcents ?? 0) + (right.output_cost_microcents ?? 0),
    total_cost_microcents: (left.total_cost_microcents ?? 0) + (right.total_cost_microcents ?? 0),
    avg_duration_ms: weightedAverage(left.avg_duration_ms, left.requests, right.avg_duration_ms, right.requests),
    p50_duration_ms: null,
    p95_duration_ms: null,
    avg_ttfb_ms: weightedAverage(left.avg_ttfb_ms, left.requests, right.avg_ttfb_ms, right.requests),
    p50_ttfb_ms: null,
    p95_ttfb_ms: null,
    avg_output_tps: weightedAverage(left.avg_output_tps, left.requests, right.avg_output_tps, right.requests),
    success_count: (left.success_count ?? 0) + (right.success_count ?? 0),
    error_count: (left.error_count ?? 0) + (right.error_count ?? 0),
    sample_count: (left.sample_count ?? 0) + (right.sample_count ?? 0),
  }
}

export function isMissingUniqueUsersColumn(cause: unknown): boolean {
  return errorText(cause).includes("Unknown column 'unique_users'")
}

export function omitUniqueUsers<T extends { unique_users?: number }>(rows: T[]) {
  return rows.map((row) => {
    const result = { ...row }
    delete result.unique_users
    return result
  })
}

export function statPeriodKey(row: StatBaseRow) {
  return [row.grain, row.period_key, row.dataset, row.tier, row.client, row.source].join("\u0000")
}

export function statRowScope(rows: StatBaseRow[]) {
  if (rows.length === 0) return
  return {
    grains: unique(rows.map((row) => row.grain)),
    periodKeys: unique(rows.map((row) => row.period_key)),
    datasets: unique(rows.map((row) => row.dataset ?? "all")),
    clients: unique(rows.map((row) => row.client ?? "all")),
    sources: unique(rows.map((row) => row.source ?? "all")),
  }
}

export function periodKeyFor(grain: StatGrain, periodStart: Date) {
  if (grain === "week") return isoWeekId(periodStart)
  return utcDateId(periodStart)
}

export function startOfUtcDay(value: Date) {
  return new Date(Date.UTC(value.getUTCFullYear(), value.getUTCMonth(), value.getUTCDate()))
}

export function startOfIsoWeek(value: Date) {
  return new Date(
    Date.UTC(value.getUTCFullYear(), value.getUTCMonth(), value.getUTCDate() - (value.getUTCDay() || 7) + 1),
  )
}

export function isoWeekId(value: Date) {
  const thursday = new Date(
    Date.UTC(value.getUTCFullYear(), value.getUTCMonth(), value.getUTCDate() + 4 - (value.getUTCDay() || 7)),
  )
  return `${thursday.getUTCFullYear()}-W${String(Math.ceil(((thursday.getTime() - Date.UTC(thursday.getUTCFullYear(), 0, 1)) / DAY_MS + 1) / 7)).padStart(2, "0")}`
}

function utcDateId(value: Date) {
  return `${value.getUTCFullYear()}-${String(value.getUTCMonth() + 1).padStart(2, "0")}-${String(value.getUTCDate()).padStart(2, "0")}`
}

export function rankBy<T extends StatBaseRow>(rows: T[], value: (row: T) => number) {
  return new Map(rows.toSorted((a, b) => value(b) - value(a)).map((row, index) => [row, index + 1]))
}

export function rankRowsWithMarketShare<T extends StatBaseRow>(
  rows: T[],
  groupKey: (row: T) => string = statPeriodKey,
) {
  return Object.values(
    rows.reduce<Record<string, T[]>>((result, row) => {
      const key = groupKey(row)
      result[key] = [...(result[key] ?? []), row]
      return result
    }, {}),
  ).flatMap((group) => {
    const tokens = group.reduce((sum, row) => sum + (row.total_tokens ?? 0), 0)
    const requests = group.reduce((sum, row) => sum + (row.requests ?? 0), 0)
    const sessions = group.reduce((sum, row) => sum + (row.sessions ?? 0), 0)
    const tokenRanks = rankBy(group, (row) => row.total_tokens ?? 0)
    const requestRanks = rankBy(group, (row) => row.requests ?? 0)
    const sessionRanks = rankBy(group, (row) => row.sessions ?? 0)
    const costRanks = rankBy(group, (row) => row.total_cost_microcents ?? 0)
    return group.map((row) => ({
      ...row,
      market_share_tokens: share(row.total_tokens, tokens),
      market_share_requests: share(row.requests, requests),
      market_share_sessions: share(row.sessions, sessions),
      rank_by_tokens: tokenRanks.get(row) ?? null,
      rank_by_requests: requestRanks.get(row) ?? null,
      rank_by_sessions: sessionRanks.get(row) ?? null,
      rank_by_cost: costRanks.get(row) ?? null,
    }))
  })
}

export function share(value: number | null | undefined, total: number) {
  if (total <= 0) return null
  return Number(((value ?? 0) / total).toFixed(6))
}

export function chunks<T>(items: T[], size: number) {
  return Array.from({ length: Math.ceil(items.length / size) }, (_, index) =>
    items.slice(index * size, (index + 1) * size),
  )
}

function unique(values: string[]) {
  return [...new Set(values)]
}

export function inserted(column: string) {
  return sql.raw(`values(\`${column}\`)`)
}

function errorText(cause: unknown): string {
  if (cause instanceof Error) return `${cause.message} ${errorText((cause as { cause?: unknown }).cause)}`
  if (typeof cause === "object" && cause)
    return Object.values(cause as Record<string, unknown>)
      .map(errorText)
      .join(" ")
  return String(cause)
}

export function weightedAverage(
  left: number | null | undefined,
  leftWeight = 0,
  right: number | null | undefined,
  rightWeight = 0,
) {
  const totalWeight =
    (left === null || left === undefined ? 0 : leftWeight) + (right === null || right === undefined ? 0 : rightWeight)
  if (totalWeight === 0) return null
  return Number((((left ?? 0) * leftWeight + (right ?? 0) * rightWeight) / totalWeight).toFixed(2))
}

export function normalizeTier(value: string) {
  const normalized = value.toLowerCase()
  if (normalized === "paid" || normalized === "zen") return "Zen"
  if (normalized === "go") return "Go"
  if (normalized === "free") return "Free"
  if (normalized === "enterprise") return "Enterprise"
  if (normalized === "all") return "all"
  return value
}

export function normalizeCountry(value: string | undefined) {
  if (!value || value.length !== 2) return "ZZ"
  return value.toUpperCase()
}

import { Client } from "@planetscale/database"
import { Resource } from "sst/resource"

const tables = ["geo_stat", "model_stat", "provider_stat"] as const
const checkOnly = process.argv.includes("--check")

const client = new Client({ url: databaseUrl() })

const missing = await tables.reduce<Promise<(typeof tables)[number][]>>(async (promise, table) => {
  const result = await promise
  if (await hasUniqueUsersColumn(table)) {
    console.log(`unique_users column already exists on ${table}`)
    return result
  }
  return [...result, table]
}, Promise.resolve([]))

if (missing.length === 0) {
  console.log("unique_users columns complete")
  process.exit(0)
}

if (checkOnly) {
  console.log(`unique_users columns missing on ${missing.join(", ")}`)
  process.exit(1)
}

await missing.reduce((promise, table) => promise.then(() => addUniqueUsersColumn(table)), Promise.resolve())

function databaseUrl() {
  if (
    process.env.PLANETSCALE_HOST &&
    process.env.PLANETSCALE_USERNAME &&
    process.env.PLANETSCALE_PASSWORD &&
    process.env.PLANETSCALE_DATABASE
  )
    return `mysql://${encodeURIComponent(process.env.PLANETSCALE_USERNAME)}:${encodeURIComponent(
      process.env.PLANETSCALE_PASSWORD,
    )}@${process.env.PLANETSCALE_HOST}/${process.env.PLANETSCALE_DATABASE}?ssl=${encodeURIComponent(
      JSON.stringify({ rejectUnauthorized: true }),
    )}`

  return process.env.DATABASE_URL ?? Resource.StatsDatabase.url
}

async function hasUniqueUsersColumn(table: (typeof tables)[number]) {
  const result = await client.execute<{ column_name: string }>(
    "SELECT column_name FROM information_schema.columns WHERE table_schema = database() AND table_name = ? AND column_name = 'unique_users'",
    [table],
  )

  return result.rows.length > 0
}

async function addUniqueUsersColumn(table: (typeof tables)[number]) {
  await client.execute(`ALTER TABLE \`${table}\` ADD \`unique_users\` bigint NOT NULL DEFAULT 0`)
  console.log(`added unique_users column to ${table}`)
}

import { Client } from "@planetscale/database"
import { readdir } from "node:fs/promises"
