import { expect, test } from "bun:test"
import { queryR2SqlPages, R2SqlQueryError, type R2SqlData } from "./r2-sql"

test("includes the transport failure in the message used by sync logging", () => {
  const cause = new DOMException("The operation timed out.", "TimeoutError")
  const error = new R2SqlQueryError({ message: "Failed to run R2 SQL stats query", cause })

  expect(error.message).toBe("Failed to run R2 SQL stats query: TimeoutError: The operation timed out.")
  expect(error.cause).toBe(cause)
})

test("preserves an R2 response error and request details", () => {
  const error = new R2SqlQueryError({ message: "R2 SQL stats query failed", status: 400, requestId: "test-request" })

  expect(error.message).toBe("R2 SQL stats query failed")
  expect(error.status).toBe(400)
  expect(error.requestId).toBe("test-request")
})

// Execute the generated pagination SQL against real aggregate rows, including
// groups that share country/model prefixes across a page boundary.
for (const count of [0, 9999, 10000, 10001, 20005]) {
  test(`reads all ${count} aggregate rows without losing or repeating groups`, async () => {
    using db = new Database(":memory:")
    db.run("CREATE TABLE aggregates (dimension TEXT, model TEXT, country TEXT, requests TEXT)")
    db.transaction(() => {
      const insert = db.prepare("INSERT INTO aggregates VALUES (?, ?, ?, ?)")
      Array.from({ length: count }, (_, index) => {
        insert.run(
          index < 2 ? "geo" : "geo_model",
          index < 2 ? null : `model'${Math.floor(index / 3)}`,
          `country${index % 3}`,
          String(index + 1),
        )
      })
    })()
    const pages: number[] = []
    const rows = await Effect.runPromise(
      queryR2SqlPages("SELECT * FROM aggregates", ["dimension", "model", "country"], (query) =>
        Effect.sync(() => {
          const rows = db.query(query).all() as R2SqlData[]
          pages.push(rows.length)
          return rows
        }),
      ),
    )
    expect(rows).toHaveLength(count)
    expect(new Set(rows.map((row) => row.requests)).size).toBe(count)
    expect(rows.reduce((sum, row) => sum + Number(row.requests), 0)).toBe((count * (count + 1)) / 2)
    expect(pages).toHaveLength(Math.floor(count / 10000) + 1)
    expect(pages.at(-1)).toBe(count % 10000)
  })
}

test("still rejects capped results without an aggregate cursor", async () => {
  const result = await Effect.runPromise(
    queryR2SqlPages("SELECT * FROM aggregates LIMIT 10000", undefined, () =>
      Effect.succeed(Array.from({ length: 10000 }, () => ({}))),
    ).pipe(Effect.flip),
  )
  expect(result.message).toContain("10000 row limit")
})

test("propagates a later page failure instead of returning partial aggregates", async () => {
  const calls: string[] = []
  const error = new R2SqlQueryError({ message: "second page failed" })
  const result = await Effect.runPromise(
    queryR2SqlPages("SELECT * FROM aggregates", ["model"], (query) => {
      calls.push(query)
      return calls.length === 1
        ? Effect.succeed(Array.from({ length: 10000 }, (_, index) => ({ model: String(index) })))
        : Effect.fail(error)
    }).pipe(Effect.flip),
  )
  expect(result).toBe(error)
  expect(calls).toHaveLength(2)
})

test("retries a transient timeout on the same page without repeating earlier rows", async () => {
  const calls: string[] = []
  const rows = await Effect.runPromise(
    queryR2SqlPages("SELECT * FROM aggregates", ["model"], (query) => {
      calls.push(query)
      if (calls.length === 1)
        return Effect.succeed(Array.from({ length: 10000 }, (_, index) => ({ model: String(index).padStart(5, "0") })))
      if (calls.length === 2)
        return Effect.fail(new R2SqlQueryError({ message: "query timeout", status: 400, code: 40005 }))
      return Effect.succeed([{ model: "10000" }])
    }),
  )
  expect(rows).toHaveLength(10001)
  expect(new Set(rows.map((row) => row.model)).size).toBe(10001)
  expect(calls).toHaveLength(3)
  expect(calls[1]).toBe(calls[2])
  expect(calls[0]).not.toBe(calls[1])
}, 10000)

test("bounds transient retries and preserves the final error", async () => {
  const calls: string[] = []
  const error = new R2SqlQueryError({ message: "unavailable", status: 503 })
  const result = await Effect.runPromise(
    queryR2SqlPages("SELECT * FROM aggregates", undefined, (query) => {
      calls.push(query)
      return Effect.fail(error)
    }).pipe(Effect.flip),
  )
  expect(calls).toHaveLength(3)
  expect(result).toBe(error)
}, 20000)

import { Context, Effect, Layer, Schedule, Schema } from "effect"
import { Resource } from "sst/resource"

const R2_SQL_MAX_ROWS = 10_000
const R2_SQL_TIMEOUT_MS = 15 * 60_000
const R2SqlValue = Schema.Union([Schema.String, Schema.Number, Schema.Boolean, Schema.Null])
const R2SqlResponse = Schema.Struct({
  success: Schema.Boolean,
  result: Schema.optional(
    Schema.NullOr(
      Schema.Struct({
        request_id: Schema.String,
        rows: Schema.Array(Schema.Record(Schema.String, R2SqlValue)),
      }),
    ),
  ),
  errors: Schema.Array(Schema.Unknown),
})
const R2SqlApiError = Schema.Struct({ code: Schema.Number, message: Schema.String })
const decodeResponse = Schema.decodeUnknownEffect(Schema.fromJsonString(R2SqlResponse))

export type R2SqlData = Record<string, string>

export class R2SqlQueryError extends Error {
  readonly _tag = "R2SqlQueryError"
  readonly requestId?: string
  readonly status?: number
  readonly code?: number

  constructor(input: { message: string; requestId?: string; status?: number; code?: number; cause?: unknown }) {
    super(input.cause instanceof Error ? `${input.message}: ${input.cause.toString()}` : input.message, {
      cause: input.cause,
    })
    this.name = "R2SqlQueryError"
    this.requestId = input.requestId
    this.status = input.status
    this.code = input.code
  }
}

export declare namespace R2Sql {
  export interface Service {
    readonly query: (query: string, columns?: readonly string[]) => Effect.Effect<R2SqlData[], R2SqlQueryError>
  }
}

export class R2Sql extends Context.Service<R2Sql, R2Sql.Service>()("@opencode/stats/R2Sql") {
  static readonly layer: Layer.Layer<R2Sql> = Layer.succeed(
    R2Sql,
    R2Sql.of({
      query: (query, columns) => queryR2SqlPages(query, columns, fetchRows),
    }),
  )
}

// Cursor columns must uniquely identify an aggregate row. Page after aggregation
// so distinct counts, averages, and country totals retain their original scope.
export const queryR2SqlPages = Effect.fn("R2Sql.query")(function* (
  query: string,
  columns: readonly string[] | undefined,
  fetchRows: (query: string) => Effect.Effect<R2SqlData[], R2SqlQueryError>,
) {
  const rows: R2SqlData[] = []
  let cursor: R2SqlData | undefined
  while (true) {
    const page = yield* Effect.suspend(() =>
      fetchRows(columns?.length ? pageQuery(query, columns, cursor) : query),
    ).pipe(
      // Retry only this page; a transient R2 timeout must not discard the whole
      // display-window backfill. Syntax, auth, and row-limit errors still fail.
      Effect.retry({
        times: 2,
        schedule: Schedule.exponential("5 seconds"),
        while: (error) =>
          error.code === 40005 || error.status === 429 || (error.status !== undefined && error.status >= 500),
      }),
    )
    if (page.length >= R2_SQL_MAX_ROWS && !columns?.length)
      return yield* Effect.fail(
        new R2SqlQueryError({ message: `R2 SQL stats query reached the ${R2_SQL_MAX_ROWS} row limit` }),
      )
    rows.push(...page)
    if (page.length < R2_SQL_MAX_ROWS) return rows
    cursor = page.at(-1)!
  }
})

function pageQuery(query: string, columns: readonly string[], cursor?: R2SqlData) {
  const keys = columns.map((column) => `COALESCE("${column.replace(/"/g, '""')}", '')`)
  const values = columns.map((column) => `'${(cursor?.[column] ?? "").replace(/'/g, "''")}'`)
  const after = keys.map((key, index) =>
    [
      ...keys.slice(0, index).map((prefix, before) => `${prefix} = ${values[before]}`),
      `${key} > ${values[index]}`,
    ].join(" AND "),
  )
  return `SELECT * FROM (${query}) AS stats_page
${cursor ? `WHERE ${after.map((condition) => `(${condition})`).join(" OR ")}` : ""}
ORDER BY ${keys.join(", ")}
LIMIT ${R2_SQL_MAX_ROWS}`
}

const fetchRows = Effect.fn("R2Sql.fetchRows")(function* (query: string) {
  const startedAt = Date.now()
  const response = yield* Effect.tryPromise({
    try: (signal) => {
      const options = {
        method: "POST",
        // Analytical queries can exceed Bun's default five-minute idle timer.
        // Bound the whole request and cancel it when the sync is interrupted.
        timeout: false,
        signal: AbortSignal.any([signal, AbortSignal.timeout(R2_SQL_TIMEOUT_MS)]),
        headers: {
          Authorization: `Bearer ${Resource.R2SqlAuthToken.value}`,
          "Content-Type": "application/json",
        },
        body: JSON.stringify({ query }),
      }
      return Bun.fetch(
        `https://api.sql.cloudflarestorage.com/api/v1/accounts/${Resource.R2Sql.accountId}/r2-sql/query/${Resource.R2Sql.bucket}`,
        options,
      )
    },
    catch: (cause) =>
      new R2SqlQueryError({
        message: `Failed to run R2 SQL stats query after ${Date.now() - startedAt}ms`,
        cause,
      }),
  })
  const body = yield* Effect.tryPromise({
    try: () => response.text(),
    catch: (cause) =>
      new R2SqlQueryError({ message: "Failed to read R2 SQL stats response", status: response.status, cause }),
  })
  const decoded = yield* decodeResponse(body).pipe(
    Effect.mapError(
      (cause) =>
        new R2SqlQueryError({
          message: "R2 SQL returned an invalid stats response",
          status: response.status,
          cause,
        }),
    ),
  )
  if (!response.ok || !decoded.success || !decoded.result)
    return yield* Effect.fail(
      new R2SqlQueryError({
        message: `R2 SQL stats query failed: ${JSON.stringify(decoded.errors)}`,
        requestId: decoded.result?.request_id,
        status: response.status,
        code: decoded.errors.find(Schema.is(R2SqlApiError))?.code,
      }),
    )

  return decoded.result.rows.map((row) =>
    Object.fromEntries(Object.entries(row).flatMap(([key, value]) => (value === null ? [] : [[key, String(value)]]))),
  )
})

import { DateTime, Effect } from "effect"
import { Resource } from "sst/resource"
import { DatabaseError } from "./database"
import { GeoStatRepo, rowsFromAggregates as geoRowsFromAggregates } from "./domain/geo"
import {
  buildRetentionQueries,
  buildStatsQueries,
  toGeoAggregate,
  toModelAggregate,
  toProviderAggregate,
  toRetentionAggregate,
} from "./domain/inference"
import { ModelStatRepo, rowsFromAggregates as modelRowsFromAggregates } from "./domain/model"
import { ProviderStatRepo, rowsFromAggregates as providerRowsFromAggregates } from "./domain/provider"
import { RetentionStatRepo, rowsFromAggregates as retentionRowsFromAggregates } from "./domain/retention"
import { startOfIsoWeek, startOfUtcDay } from "./domain/stat"
import { R2Sql, R2SqlQueryError } from "./r2-sql"

const DATALAKE_INGESTION_LAG_MS = 5 * 60_000
const STATS_DATA_START_MS = new Date("2026-05-28T00:00:00.000Z").getTime()
const WEEK_MS = 7 * 86_400_000
const DISPLAY_WINDOW_MS = 56 * 86_400_000
// A retention result needs one complete activity week plus its complete return
// week. Keep another partial week of slack around the ISO-week boundary.
const RETENTION_INCREMENTAL_LOOKBACK_MS = 16 * 86_400_000
// Anchor incremental passes to the ISO week containing this lookback, so the pass
// after a week boundary still recomputes the previous week's final aggregates even
// if the boundary pass itself failed.
const INCREMENTAL_LOOKBACK_MS = 2 * 3_600_000

export type SyncStatsResult = { ok: true; rows: number; startedAt: string; periodStart: string; periodEnd: string }
export type SyncStatsError = R2SqlQueryError | DatabaseError
type SyncStatsServices = R2Sql | ModelStatRepo | ProviderStatRepo | GeoStatRepo | RetentionStatRepo

export const syncStats: (options?: {
  full?: boolean
}) => Effect.Effect<SyncStatsResult, SyncStatsError, SyncStatsServices> = Effect.fn("StatSync.sync")(
  function* (options?: { full?: boolean }) {
    const startedAt = yield* DateTime.nowAsDate
    const periodEnd = new Date(Math.floor((startedAt.getTime() - DATALAKE_INGESTION_LAG_MS) / 60_000) * 60_000)
    const periodStart = options?.full ? fullPeriodStart(periodEnd) : incrementalPeriodStart(periodEnd)
    const r2Sql = yield* R2Sql
    const modelStats = yield* ModelStatRepo
    const providerStats = yield* ProviderStatRepo
    const geoStats = yield* GeoStatRepo
    const retentionStats = yield* RetentionStatRepo

    yield* logRuntimeCheck()

    const queries = buildStatsQueries(periodStart, periodEnd)
    yield* Effect.logInfo(
      `stats sync started ${JSON.stringify({ full: options?.full ?? false, periodStart, periodEnd, queries: queries.length })}`,
    )
    const rows = yield* Effect.forEach(
      queries,
      (query, index) =>
        r2Sql.query(query, ["dimension", "tier", "provider", "model", "country"]).pipe(
          Effect.tap((rows) =>
            Effect.logInfo(
              `stats query complete ${JSON.stringify({ index, total: queries.length, rows: rows.length })}`,
            ),
          ),
          Effect.tapError((error) =>
            Effect.logError(
              `stats query failed ${JSON.stringify({ index, total: queries.length, error: error.message })}`,
            ),
          ),
        ),
      {
        concurrency: 4,
      },
    ).pipe(Effect.map((batches) => batches.flat()))
    const modelRows = modelRowsFromAggregates(rows.filter((row) => row.dimension === "model").flatMap(toModelAggregate))
    const providerRows = providerRowsFromAggregates(
      rows.filter((row) => row.dimension === "provider").flatMap(toProviderAggregate),
    )
    const geoRows = geoRowsFromAggregates(
      rows.filter((row) => row.dimension === "geo" || row.dimension === "geo_model").flatMap(toGeoAggregate),
    )
    const retentionAvailable = yield* retentionStats.available()
    const retentionQueries = retentionAvailable
      ? buildRetentionQueries(
          options?.full
            ? periodStart
            : new Date(
