    expect(moveFileTreeSelectionToFile(rows, tui.id, 1)).toBe(index.id)
    expect(moveFileTreeSelectionToFile(rows, index.id, -1)).toBe(tui.id)
    expect(moveFileTreeSelectionToFile(rows, readme.id, 1)).toBe(readme.id)
