export const Sizes = {
  render: () => (
    <div style={{ display: "flex", gap: "16px", "align-items": "center" }}>
      <mod.Spinner style={{ width: "12px", height: "12px" }} />
      <mod.Spinner style={{ width: "20px", height: "20px" }} />
      <mod.Spinner style={{ width: "28px", height: "28px" }} />
    </div>
