export const Playground = {
  render: () => {
    const [state, setState] = createStore({
      heading: HEADINGS[0],
      headingIndex: 0,
      active: true,
      cycling: false,
      duration: 550,
      blur: 2,
      travel: 4,
      bounce: 1.35,
      maskSize: 12,
      maskPad: 9,
      maskHeight: 0,
      debug: false,
      odoBlur: false,
    })
    const heading = () => state.heading
    const headingIndex = () => state.headingIndex
    const active = () => state.active
    const cycling = () => state.cycling
    const duration = () => state.duration
    const blur = () => state.blur
    const travel = () => state.travel
    const bounce = () => state.bounce
    const maskSize = () => state.maskSize
    const maskPad = () => state.maskPad
    const maskHeight = () => state.maskHeight
    const debug = () => state.debug
    const odoBlur = () => state.odoBlur
    let cycleTimer

    const nextHeading = () => {
      const next = (headingIndex() + 1) % HEADINGS.length
      setState("headingIndex", next)
      setState("heading", HEADINGS[next])
    }

    const prevHeading = () => {
      const prev = (headingIndex() - 1 + HEADINGS.length) % HEADINGS.length
      setState("headingIndex", prev)
      setState("heading", HEADINGS[prev])
    }

    const toggleCycling = () => {
      if (cycling()) {
        clearTimeout(cycleTimer)
        cycleTimer = undefined
        setState("cycling", false)
        return
      }
      setState("cycling", true)
      const tick = () => {
        if (!cycling()) return
        nextHeading()
        cycleTimer = setTimeout(tick, 850 + Math.floor(Math.random() * 550))
      }
      cycleTimer = setTimeout(tick, 850 + Math.floor(Math.random() * 550))
    }

    const clearHeading = () => {
      setState("heading", undefined)
      if (cycling()) {
        clearTimeout(cycleTimer)
        cycleTimer = undefined
        setState("cycling", false)
      }
    }

    onCleanup(() => {
      if (cycleTimer) clearTimeout(cycleTimer)
    })

    const vars = () => ({
      "--h-duration": `${duration()}ms`,
      "--h-duration-raw": `${duration()}`,
      "--h-blur": `${blur()}px`,
      "--h-travel": `${travel()}px`,
      "--h-spring": `cubic-bezier(0.34, ${bounce()}, 0.64, 1)`,
      "--h-spring-soft": `cubic-bezier(0.34, ${Math.max(bounce() * 0.7, 1)}, 0.64, 1)`,
      "--h-mask-size": `${maskSize()}px`,
      "--h-mask-pad": `${maskPad()}px`,
      "--h-mask-height": `${maskHeight()}px`,
      "--h-mask-bg": "#1a1a1a",
    })

    return (
      <div style={{ display: "grid", gap: "24px", padding: "20px", "max-width": "820px", ...vars() }}>
        <style>{STYLES}</style>

        {/* ── Variant cards ─────────────────────────────────── */}
        <div style={{ display: "grid", "grid-template-columns": "1fr", gap: "16px" }}>
          <div style={cardStyle}>
            <span style={cardLabel}>TextReveal (production)</span>
            <span style={thinkingRow}>
              <TextShimmer text="Thinking" active={active()} />
              <span style={headingSlot}>
                <TextReveal
                  text={heading()}
                  duration={duration()}
                  travel={25}
                  edge={17}
                  spring={`cubic-bezier(0.34, ${bounce()}, 0.64, 1)`}
                  springSoft={`cubic-bezier(0.34, ${Math.max(bounce() * 0.7, 1)}, 0.64, 1)`}
                  growOnly
                />
              </span>
            </span>
          </div>
          {VARIANTS.map((v) => (
            <div style={cardStyle}>
              <span style={cardLabel}>{v.label}</span>
              <span style={thinkingRow}>
                <TextShimmer text="Thinking" active={active()} />
                <span style={headingSlot}>
                  <AnimatedHeading
                    text={heading()}
                    variant={v.key}
                    debug={v.key === "odometer" && debug()}
                    odoBlur={v.key === "odometer" && odoBlur()}
                  />
                </span>
              </span>
            </div>
          ))}
        </div>

        {/* ── Sliders ──────────────────────────────────────── */}
        <div
          style={{
            "border-top": "1px solid var(--color-divider, #333)",
            "padding-top": "16px",
            display: "grid",
            gap: "10px",
          }}
        >
          <div style={{ display: "flex", "align-items": "center", gap: "12px" }}>
            <span style={sliderLabel}>duration</span>
            <input
              type="range"
              class="heading-slider"
              min={200}
              max={1400}
              step={50}
              value={duration()}
              onInput={(e) => setState("duration", Number(e.currentTarget.value))}
            />
            <span style={sliderValue}>{duration()}ms</span>
          </div>

          <div style={{ display: "flex", "align-items": "center", gap: "12px" }}>
            <span style={sliderLabel}>blur</span>
            <input
              type="range"
              class="heading-slider"
              min={0}
              max={16}
              step={0.5}
              value={blur()}
              onInput={(e) => setState("blur", Number(e.currentTarget.value))}
            />
            <span style={sliderValue}>{blur()}px</span>
          </div>

          <div style={{ display: "flex", "align-items": "center", gap: "12px" }}>
            <span style={sliderLabel}>travel</span>
            <input
              type="range"
              class="heading-slider"
              min={4}
              max={120}
              step={1}
              value={travel()}
              onInput={(e) => setState("travel", Number(e.currentTarget.value))}
            />
            <span style={sliderValue}>{travel()}px</span>
          </div>

          <div style={{ display: "flex", "align-items": "center", gap: "12px" }}>
            <span style={sliderLabel}>bounce</span>
            <input
              type="range"
              class="heading-slider"
              min={1}
              max={2.2}
              step={0.05}
              value={bounce()}
              onInput={(e) => setState("bounce", Number(e.currentTarget.value))}
            />
            <span style={sliderValue}>
              {bounce().toFixed(2)} {bounce() <= 1.05 ? "(none)" : bounce() >= 1.9 ? "(heavy)" : ""}
            </span>
          </div>

          <div style={{ display: "flex", "align-items": "center", gap: "12px" }}>
            <span style={sliderLabel}>mask</span>
            <input
              type="range"
              class="heading-slider"
              min={0}
              max={50}
              step={1}
              value={maskSize()}
              onInput={(e) => setState("maskSize", Number(e.currentTarget.value))}
            />
            <span style={sliderValue}>
              {maskSize()}px {maskSize() === 0 ? "(hard)" : ""}
            </span>
          </div>

          <div style={{ display: "flex", "align-items": "center", gap: "12px" }}>
            <span style={sliderLabel}>mask pad</span>
            <input
              type="range"
              class="heading-slider"
              min={0}
              max={60}
              step={1}
              value={maskPad()}
              onInput={(e) => setState("maskPad", Number(e.currentTarget.value))}
            />
            <span style={sliderValue}>{maskPad()}px</span>
          </div>

          <div style={{ display: "flex", "align-items": "center", gap: "12px" }}>
            <span style={sliderLabel}>mask height</span>
            <input
              type="range"
              class="heading-slider"
              min={0}
              max={80}
              step={1}
              value={maskHeight()}
              onInput={(e) => setState("maskHeight", Number(e.currentTarget.value))}
            />
            <span style={sliderValue}>{maskHeight()}px</span>
          </div>
        </div>

        {/* ── Controls ─────────────────────────────────────── */}
        <div style={{ display: "grid", gap: "12px" }}>
          <div style={{ display: "flex", gap: "8px", "flex-wrap": "wrap" }}>
            <button onClick={toggleCycling} style={btn(cycling())}>
              {cycling() ? "Stop sim" : "Simulate jitter"}
            </button>
            <button onClick={prevHeading} style={btn()}>
              Prev
            </button>
            <button onClick={nextHeading} style={btn()}>
              Next
            </button>
            <button onClick={clearHeading} style={btn()}>
              Clear
            </button>
            <button onClick={() => setState("active", (value) => !value)} style={smallBtn(active())}>
              {active() ? "Shimmer: on" : "Shimmer: off"}
            </button>
            <button onClick={() => setState("debug", (value) => !value)} style={smallBtn(debug())}>
              {debug() ? "Debug mask: on" : "Debug mask"}
            </button>
            <button onClick={() => setState("odoBlur", (value) => !value)} style={smallBtn(odoBlur())}>
              {odoBlur() ? "Odo blur: on" : "Odo blur"}
            </button>
          </div>

          <div style={{ display: "flex", gap: "6px", "flex-wrap": "wrap" }}>
            {HEADINGS.map((h, i) => (
              <button
                onClick={() => {
                  setState("headingIndex", i)
                  setState("heading", h)
                }}
                style={smallBtn(headingIndex() === i)}
              >
                {h ?? "(no submessage)"}
              </button>
            ))}
          </div>

          <div
            style={{
              "font-size": "11px",
              color: "var(--color-text-weak, #888)",
              "font-family": "monospace",
            }}
          >
            heading: {heading() ?? "(none)"} · sim: {cycling() ? "on" : "off"} · bounce: {bounce().toFixed(2)} ·
            odo-blur: {odoBlur() ? "on" : "off"}
          </div>
        </div>
      </div>
    )
  },
}

import { Toast as Kobalte, toaster } from "@kobalte/core/toast"
import type { ToastRootProps, ToastCloseButtonProps, ToastTitleProps, ToastDescriptionProps } from "@kobalte/core/toast"
import type { ComponentProps, JSX } from "solid-js"
import { Show } from "solid-js"
import { Portal } from "solid-js/web"
import { useI18n } from "../context/i18n"
import { Icon, type IconProps } from "./icon"
import { IconButton } from "./icon-button"

export interface ToastRegionProps extends ComponentProps<typeof Kobalte.Region> {}

function ToastRegion(props: ToastRegionProps) {
  return (
    <Portal>
      <Kobalte.Region data-component="toast-region" {...props}>
        <Kobalte.List data-slot="toast-list" />
      </Kobalte.Region>
    </Portal>
  )
}

export interface ToastRootComponentProps extends ToastRootProps {
  class?: string
  classList?: ComponentProps<"li">["classList"]
  children?: JSX.Element
}

function ToastRoot(props: ToastRootComponentProps) {
  return (
    <Kobalte
      data-component="toast"
      classList={{
        ...props.classList,
        [props.class ?? ""]: !!props.class,
      }}
      {...props}
    />
  )
}

function ToastIcon(props: { name: IconProps["name"] }) {
  return (
    <div data-slot="toast-icon">
      <Icon name={props.name} />
    </div>
  )
}

function ToastContent(props: ComponentProps<"div">) {
  return <div data-slot="toast-content" {...props} />
}

function ToastTitle(props: ToastTitleProps & ComponentProps<"div">) {
  return <Kobalte.Title data-slot="toast-title" {...props} />
}

function ToastDescription(props: ToastDescriptionProps & ComponentProps<"div">) {
  return <Kobalte.Description data-slot="toast-description" {...props} />
}

function ToastActions(props: ComponentProps<"div">) {
  return <div data-slot="toast-actions" {...props} />
}

function ToastCloseButton(props: ToastCloseButtonProps & ComponentProps<"button">) {
  const i18n = useI18n()
  return (
    <Kobalte.CloseButton
      data-slot="toast-close-button"
      as={IconButton}
      icon="close"
      variant="ghost"
      aria-label={i18n.t("ui.common.dismiss")}
      {...props}
    />
  )
}

function ToastProgressTrack(props: ComponentProps<typeof Kobalte.ProgressTrack>) {
  return <Kobalte.ProgressTrack data-slot="toast-progress-track" {...props} />
}

function ToastProgressFill(props: ComponentProps<typeof Kobalte.ProgressFill>) {
  return <Kobalte.ProgressFill data-slot="toast-progress-fill" {...props} />
}

export const Toast = Object.assign(ToastRoot, {
  Region: ToastRegion,
  Icon: ToastIcon,
  Content: ToastContent,
  Title: ToastTitle,
  Description: ToastDescription,
  Actions: ToastActions,
  CloseButton: ToastCloseButton,
  ProgressTrack: ToastProgressTrack,
  ProgressFill: ToastProgressFill,
})

export { toaster }

export type ToastVariant = "default" | "success" | "error" | "loading"

export interface ToastAction {
  label: string
  onClick: "dismiss" | (() => void)
}

export interface ToastOptions {
  title?: string
  description?: string
  icon?: IconProps["name"]
  variant?: ToastVariant
  duration?: number
  persistent?: boolean
  actions?: ToastAction[]
}

export function showToast(options: ToastOptions | string) {
  const opts = typeof options === "string" ? { description: options } : options
  return toaster.show((props) => (
    <Toast
      toastId={props.toastId}
      duration={opts.duration}
      persistent={opts.persistent}
      data-variant={opts.variant ?? "default"}
    >
      <Show when={opts.icon}>
        <Toast.Icon name={opts.icon!} />
      </Show>
      <Toast.Content>
        <Show when={opts.title}>
          <Toast.Title>{opts.title}</Toast.Title>
        </Show>
        <Show when={opts.description}>
          <Toast.Description>{opts.description}</Toast.Description>
        </Show>
        <Show when={opts.actions?.length}>
          <Toast.Actions>
            {opts.actions!.map((action) => (
              <button
                data-slot="toast-action"
                onClick={() => {
                  if (typeof action.onClick === "function") {
                    action.onClick()
                  }
                  toaster.dismiss(props.toastId)
                }}
              >
                {action.label}
              </button>
            ))}
          </Toast.Actions>
        </Show>
      </Toast.Content>
      <Toast.CloseButton />
    </Toast>
  ))
}

export interface ToastPromiseOptions<T, U = unknown> {
  loading?: JSX.Element
  success?: (data: T) => JSX.Element
  error?: (error: U) => JSX.Element
}

export function showPromiseToast<T, U = unknown>(
  promise: Promise<T> | (() => Promise<T>),
  options: ToastPromiseOptions<T, U>,
) {
  return toaster.promise(promise, (props) => (
    <Toast
      toastId={props.toastId}
      data-variant={props.state === "pending" ? "loading" : props.state === "fulfilled" ? "success" : "error"}
    >
      <Toast.Content>
        <Toast.Description>
          {props.state === "pending" && options.loading}
          {props.state === "fulfilled" && options.success?.(props.data!)}
          {props.state === "rejected" && options.error?.(props.error)}
        </Toast.Description>
      </Toast.Content>
      <Toast.CloseButton />
    </Toast>
  ))
}

