              </Match>
            </Switch>
            <IconHashtag width={18} height={18} />
            <IconCheckCircle width={18} height={18} />
          </a>
          <span data-slot="tooltip">{messages.copied}</span>
        </div>
        <div data-slot="bar"></div>
